INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (8, 'M08.18', 'Exam Question Bank', 18)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The ISA', '[{"id": "a", "text": "assumes a standard day.", "correct": false}, {"id": "b", "text": "is taken from the equator.", "correct": false}, {"id": "c", "text": "is taken from 45 degrees latitude.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At higher altitudes as altitude increases, pressure', '[{"id": "a", "text": "decreases at constant rate.", "correct": false}, {"id": "b", "text": "decreases exponentially.", "correct": true}, {"id": "c", "text": "increases exponentially.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When the pressure is half of that at sea level, what is the altitude?', '[{"id": "a", "text": "12,000 ft.", "correct": false}, {"id": "b", "text": "18,000 ft.", "correct": true}, {"id": "c", "text": "8,000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If gauge pressure on a standard day at sea level is 25 PSI, the absolute pressure is', '[{"id": "a", "text": "39.7 PSI.", "correct": true}, {"id": "b", "text": "10.3 PSI.", "correct": false}, {"id": "c", "text": "43.8 PSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Pressure decreases', '[{"id": "a", "text": "inversely proportional to temperature.", "correct": false}, {"id": "b", "text": "proportionally with a decreases in temperature.", "correct": true}, {"id": "c", "text": "Pressure and temperature are not related.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As air gets colder, the service ceiling of an aircraft', '[{"id": "a", "text": "reduces.", "correct": false}, {"id": "b", "text": "increases.", "correct": true}, {"id": "c", "text": "remains the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is sea level pressure?', '[{"id": "a", "text": "1012.3 mb.", "correct": false}, {"id": "b", "text": "1013.2 mb.", "correct": true}, {"id": "c", "text": "1032.2 mb.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'How does IAS at the point of stall vary with height?', '[{"id": "a", "text": "It decreases.", "correct": false}, {"id": "b", "text": "It is practically constant.", "correct": true}, {"id": "c", "text": "It increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is the lapse rate with regard to temperature?', '[{"id": "a", "text": "4°C per 1000 ft.", "correct": false}, {"id": "b", "text": "1.98°C per 1000 ft.", "correct": true}, {"id": "c", "text": "1.98°F per 1000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Standard sea level temperature is', '[{"id": "a", "text": "20 degrees Celsius.", "correct": false}, {"id": "b", "text": "0 degrees Celsius.", "correct": false}, {"id": "c", "text": "15 degrees Celsius.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As altitude increases, pressure', '[{"id": "a", "text": "decreases exponentially.", "correct": true}, {"id": "b", "text": "decreases at constant rate.", "correct": false}, {"id": "c", "text": "increases exponentially.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lapse rate usually refers to', '[{"id": "a", "text": "density.", "correct": false}, {"id": "b", "text": "pressure.", "correct": false}, {"id": "c", "text": "temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Temperature above 36,000 feet will', '[{"id": "a", "text": "increase exponentially.", "correct": false}, {"id": "b", "text": "decrease exponentially.", "correct": false}, {"id": "c", "text": "remain constant.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With increasing altitude pressure decreases and', '[{"id": "a", "text": "temperature decreases at the same rate as pressure reduces.", "correct": false}, {"id": "b", "text": "temperature decreases but at a lower rate than pressure reduces.", "correct": true}, {"id": "c", "text": "temperature remains constant to 8000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is the temperature in comparison to ISA conditions at 30,000ft?', '[{"id": "a", "text": "-60°C.", "correct": false}, {"id": "b", "text": "0°C.", "correct": false}, {"id": "c", "text": "-45°C.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At what altitude is the tropopause?', '[{"id": "a", "text": "36,000 ft.", "correct": true}, {"id": "b", "text": "57,000 ft.", "correct": false}, {"id": "c", "text": "63,000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What approximate percentage of oxygen is in the atmosphere?', '[{"id": "a", "text": "12%.", "correct": false}, {"id": "b", "text": "21%.", "correct": true}, {"id": "c", "text": "78%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which has the greater density?', '[{"id": "a", "text": "Air at low altitude.", "correct": true}, {"id": "b", "text": "Air at high altitude.", "correct": false}, {"id": "c", "text": "It remains constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At what altitude does stratosphere commence approximately?', '[{"id": "a", "text": "Sea level.", "correct": false}, {"id": "b", "text": "36,000 ft.", "correct": true}, {"id": "c", "text": "63,000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A pressure of one atmosphere is equal to', '[{"id": "a", "text": "14.7 psi.", "correct": true}, {"id": "b", "text": "1 inch Hg.", "correct": false}, {"id": "c", "text": "100 millibar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The millibar is a unit of', '[{"id": "a", "text": "atmospheric temperature.", "correct": false}, {"id": "b", "text": "pressure altitude.", "correct": false}, {"id": "c", "text": "barometric pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With an increase in altitude under I.S.A. conditions the temperature in the troposphere', '[{"id": "a", "text": "remains constant.", "correct": false}, {"id": "b", "text": "decreases.", "correct": true}, {"id": "c", "text": "increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A barometer indicates', '[{"id": "a", "text": "pressure.", "correct": true}, {"id": "b", "text": "density.", "correct": false}, {"id": "c", "text": "temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which condition is the actual amount of water vapour in a mixture of air and water?', '[{"id": "a", "text": "Relative humidity.", "correct": false}, {"id": "b", "text": "Absolute humidity.", "correct": true}, {"id": "c", "text": "Dew point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which will weigh the least?', '[{"id": "a", "text": "98 parts of dry air and 2 parts of water vapour.", "correct": false}, {"id": "b", "text": "50 parts of dry air and 50 parts of water vapour.", "correct": false}, {"id": "c", "text": "35 parts of dry air and 65 parts of water vapour.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which is the ratio of the water vapour actually present in the atmosphere to the amount that would be present if the air were saturated at the prevailing temperature and pressure?', '[{"id": "a", "text": "Absolute humidity.", "correct": false}, {"id": "b", "text": "Dew point.", "correct": false}, {"id": "c", "text": "Relative humidity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The speed of sound in the atmosphere', '[{"id": "a", "text": "changes with a change in pressure.", "correct": false}, {"id": "b", "text": "varies according to the frequency of the sound.", "correct": false}, {"id": "c", "text": "changes with a change in temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is sea level pressure?', '[{"id": "a", "text": "1032.2 mb.", "correct": false}, {"id": "b", "text": "1012.3 mb.", "correct": false}, {"id": "c", "text": "1013.2 mb.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which statement concerning heat and/or temperature is true?', '[{"id": "a", "text": "Temperature is a measure of the kinetic energy of the molecules of any substance.", "correct": true}, {"id": "b", "text": "Temperature is a measure of the potential energy of the molecules of any substance.", "correct": false}, {"id": "c", "text": "There is an inverse relationship between temperature and heat.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is absolute humidity?', '[{"id": "a", "text": "The amount of water vapor, usually discussed per unit volume.", "correct": true}, {"id": "b", "text": "The temperature to which humid air must be cooled at constant pressure to become saturated.", "correct": false}, {"id": "c", "text": "The amount of water vapor in a mixture of air and water vapor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The temperature to which humid air must be cooled at constant pressure to become saturated is called', '[{"id": "a", "text": "absolute humidity.", "correct": false}, {"id": "b", "text": "dew point.", "correct": true}, {"id": "c", "text": "relative humidity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Above 65,800 ft temperature', '[{"id": "a", "text": "decreases by 1.98°C up to 115,000 ft.", "correct": false}, {"id": "b", "text": "remains constant up to 115,000 ft.", "correct": false}, {"id": "c", "text": "increases by 0.303°C up to 115,000 ft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At sea level, ISA atmospheric pressure is', '[{"id": "a", "text": "14.7 kPa.", "correct": false}, {"id": "b", "text": "10 Bar.", "correct": false}, {"id": "c", "text": "14.7 PSI.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a very hot day with ambient temperature higher than ISA, the pressure altitude is 20,000 ft. How much will the density altitude be?', '[{"id": "a", "text": "The same.", "correct": false}, {"id": "b", "text": "Greater than 20,000 ft.", "correct": true}, {"id": "c", "text": "Less than 20,000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The atmospheric zone where the temperature remains fairly constant is called the', '[{"id": "a", "text": "stratosphere.", "correct": true}, {"id": "b", "text": "ionosphere.", "correct": false}, {"id": "c", "text": "troposphere.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In the ISA the height of the tropopause is', '[{"id": "a", "text": "11,000 feet.", "correct": false}, {"id": "b", "text": "11,000 metres.", "correct": true}, {"id": "c", "text": "36,000 metres.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In the ISA the sea level pressure is taken to be', '[{"id": "a", "text": "14 PSI.", "correct": false}, {"id": "b", "text": "1013.2 mb.", "correct": true}, {"id": "c", "text": "1.013 mb.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In the ISA the temperature lapse rate with altitude is taken to be:', '[{"id": "a", "text": "dependent on pressure and density changes.", "correct": false}, {"id": "b", "text": "linear.", "correct": true}, {"id": "c", "text": "non linear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Put in sequence from the ground up', '[{"id": "a", "text": "tropopause, stratosphere, troposphere.", "correct": false}, {"id": "b", "text": "tropopause, troposphere, stratosphere.", "correct": false}, {"id": "c", "text": "troposphere, tropopause, stratosphere.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The International Standard Atmosphere can be described as', '[{"id": "a", "text": "the atmosphere at 45 degrees north latitude.", "correct": false}, {"id": "b", "text": "the atmosphere at the equator with certain conditions.", "correct": false}, {"id": "c", "text": "the atmosphere which can be used Worldwide to provide comparable performance results.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The temperature lapse rate below the tropopause is', '[{"id": "a", "text": "1°C per 1000 ft.", "correct": false}, {"id": "b", "text": "2°C per 1000 ft.", "correct": true}, {"id": "c", "text": "3°C per 1000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Above the tropopause air pressure', '[{"id": "a", "text": "decreases at a constant rate.", "correct": false}, {"id": "b", "text": "decreases exponentially.", "correct": true}, {"id": "c", "text": "increases exponentially.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following is correct?', '[{"id": "a", "text": "Absolute pressure + Atmospheric pressure = Gauge pressure.", "correct": false}, {"id": "b", "text": "Absolute pressure = Gauge pressure + Atmospheric pressure.", "correct": true}, {"id": "c", "text": "Atmospheric pressure = Absolute pressure + Gauge pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the altitude increases what happens of the ratio of Nitrogen to Oxygen?', '[{"id": "a", "text": "Increases.", "correct": false}, {"id": "b", "text": "Decreases.", "correct": false}, {"id": "c", "text": "Stays the same.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What happens to the density of air as altitude is increased?', '[{"id": "a", "text": "Decreases.", "correct": true}, {"id": "b", "text": "Stays the same.", "correct": false}, {"id": "c", "text": "Increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft is travelling at a speed of 720 nautical miles per hour. To calculate speed in MPH you', '[{"id": "a", "text": "divide by 0.83.", "correct": false}, {"id": "b", "text": "multipy by 0.83.", "correct": false}, {"id": "c", "text": "multiply by 1.15.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The CofP is the point where', '[{"id": "a", "text": "the lift can be said to act.", "correct": true}, {"id": "b", "text": "the three axis of rotation meet.", "correct": false}, {"id": "c", "text": "all the forces on an aircraft act.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At stall, the wingtip stagnation point', '[{"id": "a", "text": "doesn''t move.", "correct": false}, {"id": "b", "text": "moves toward the lower surface of the wing.", "correct": true}, {"id": "c", "text": "moves toward the upper surface of the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The rigging angle of incidence of an elevator is', '[{"id": "a", "text": "the angle between the bottom surface of the elevator and the longitudinal datum.", "correct": true}, {"id": "b", "text": "the angle between the bottom surface of the elevator and the horizontal in the rigging position.", "correct": false}, {"id": "c", "text": "the angle between the mean chord line and the horizontal in the rigging position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following is true?', '[{"id": "a", "text": "Lift acts at right angles to the relative airflow and weight acts vertically down.", "correct": true}, {"id": "b", "text": "Lift acts at right angles to the wing chord line and weight acts vertically down.", "correct": false}, {"id": "c", "text": "Lift acts at right angles to the relative air flow and weight acts at right angles to the aircraft centre line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What happens to air flowing at the speed of sound when it enters a converging duct?', '[{"id": "a", "text": "Velocity increases, pressure and density decreases.", "correct": false}, {"id": "b", "text": "Velocity, pressure and density increase.", "correct": false}, {"id": "c", "text": "Velocity decreases, pressure and density increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the angle of attack of an airfoil increases the centre of pressure', '[{"id": "a", "text": "remains stationary.", "correct": false}, {"id": "b", "text": "moves aft.", "correct": false}, {"id": "c", "text": "moves forward.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Vapour trails from the wingtips of an aircraft in flight are caused by', '[{"id": "a", "text": "low pressure above the wing and high pressure below the wing causing vortices.", "correct": true}, {"id": "b", "text": "low pressure above the wing and high pressure below the wing causing a temperature rise.", "correct": false}, {"id": "c", "text": "high pressure above the wing and low pressure below the wing causing vortices.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The chord line of a wing is a line that runs from', '[{"id": "a", "text": "the centre of the leading edge of the wing to the trailing edge.", "correct": true}, {"id": "b", "text": "half way between the upper and lower surface of the wing.", "correct": false}, {"id": "c", "text": "one wing tip to the other wing tip.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The angle of incidence of a wing is an angle formed by lines', '[{"id": "a", "text": "parallel to the chord line and longitudinal axis.", "correct": true}, {"id": "b", "text": "parallel to the chord line and the vertical axis.", "correct": false}, {"id": "c", "text": "parallel to the chord line and the lateral axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The centre of pressure of an aerofoil is located', '[{"id": "a", "text": "30 - 40% of the chord line forward of the leading edge.", "correct": false}, {"id": "b", "text": "50% of the chord line back from the leading edge.", "correct": false}, {"id": "c", "text": "30 - 40% of the chord line back from the leading edge.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Compressibility effect is', '[{"id": "a", "text": "drag associated with the form of an aircraft.", "correct": false}, {"id": "b", "text": "the increase in total drag of an aerofoil in transonic flight due to the formation of shock waves.", "correct": true}, {"id": "c", "text": "drag associated with the friction of the air over the surface of the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A high aspect ratio wing will give', '[{"id": "a", "text": "high profile and low induced drag.", "correct": true}, {"id": "b", "text": "low profile and high induced drag.", "correct": false}, {"id": "c", "text": "low profile and low induced drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Aerofoil efficiency is defined by', '[{"id": "a", "text": "lift over drag.", "correct": true}, {"id": "b", "text": "lift over weight.", "correct": false}, {"id": "c", "text": "drag over lift.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The relationship between induced drag and airspeed is, induced drag is', '[{"id": "a", "text": "directly proportional to the square of the speed.", "correct": false}, {"id": "b", "text": "directly proportional to speed.", "correct": false}, {"id": "c", "text": "inversely proportional to the square of the speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is the definition of Angle of Incidence?', '[{"id": "a", "text": "The angle the underside of the mainplane or tailplane makes with the horizontal.", "correct": false}, {"id": "b", "text": "The angle the underside of the mainplane or tailplane makes with the longitudinal datum line.", "correct": true}, {"id": "c", "text": "The angle the chord of the mainplane or tailplane makes with the horizontal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is the collective term for the fin and rudder and other surfaces aft of the centre of gravity that helps directional stability?', '[{"id": "a", "text": "Empennage.", "correct": false}, {"id": "b", "text": "Fuselage surfaces.", "correct": false}, {"id": "c", "text": "Effective keel surface.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A decrease in incidence toward the wing tip may be provided to', '[{"id": "a", "text": "prevent adverse yaw in a turn.", "correct": false}, {"id": "b", "text": "retain lateral control effectiveness at high angles of attack.", "correct": true}, {"id": "c", "text": "prevent span wise flow in maneuvers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Low wing loading', '[{"id": "a", "text": "increases stalling speed, landing speed and landing run.", "correct": false}, {"id": "b", "text": "increases lift, stalling speed and maneuverability.", "correct": false}, {"id": "c", "text": "decreases stalling speed, landing speed and landing run.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As a general rule, if the aerodynamic angle of incidence (angle of attack) of an aerofoil is slightly increased, the centre of pressure will', '[{"id": "a", "text": "move towards the tip.", "correct": false}, {"id": "b", "text": "move forward towards the leading edge.", "correct": true}, {"id": "c", "text": "never move.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When does the angle of incidence change?', '[{"id": "a", "text": "It never changes.", "correct": true}, {"id": "b", "text": "When the aircraft attitude changes.", "correct": false}, {"id": "c", "text": "When the aircraft is ascending or descending.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the angle of attack decreases, what happens to the centre of pressure?', '[{"id": "a", "text": "It moves rearwards.", "correct": true}, {"id": "b", "text": "Centre of pressure is not affected by angle of attack decrease.", "correct": false}, {"id": "c", "text": "It moves forward.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A decrease in pressure over the upper surface of a wing or aerofoil is responsible for', '[{"id": "a", "text": "approximately 2/3 (two thirds) of the lift obtained.", "correct": true}, {"id": "b", "text": "approximately 1/2 (one half) of the lift obtained.", "correct": false}, {"id": "c", "text": "approximately 1/3 (one third) of the lift obtained.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following types of drag increases as the aircraft gains altitude?', '[{"id": "a", "text": "Interference drag.", "correct": false}, {"id": "b", "text": "Parasite drag.", "correct": false}, {"id": "c", "text": "Induced drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The layer of air over the surface of an aerofoil which is slower moving, in relation to the rest of the airflow, is known as', '[{"id": "a", "text": "none of the above.", "correct": false}, {"id": "b", "text": "camber layer.", "correct": false}, {"id": "c", "text": "boundary layer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is a controlling factor of turbulence and skin friction?', '[{"id": "a", "text": "Countersunk rivets used on skin exterior.", "correct": false}, {"id": "b", "text": "Aspect ratio.", "correct": false}, {"id": "c", "text": "Fineness ratio.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the C of G is aft of the Centre of Pressure', '[{"id": "a", "text": "when the aircraft yaws the aerodynamic forces acting forward of the Centre of Pressure.", "correct": false}, {"id": "b", "text": "changes in lift produce a pitching moment which acts to increase the change in lift.", "correct": true}, {"id": "c", "text": "when the aircraft sideslips, the C of G causes the nose to turn into the sideslip thus applying a restoring moment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The upper part of the wing in comparison to the lower', '[{"id": "a", "text": "develops less lift.", "correct": false}, {"id": "b", "text": "develops the same lift.", "correct": false}, {"id": "c", "text": "develops more lift.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What effect would a forward CG have on an aircraft on landing?', '[{"id": "a", "text": "Increase stalling speed.", "correct": true}, {"id": "b", "text": "Reduce stalling speed.", "correct": false}, {"id": "c", "text": "No effect on landing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'QNE refers to setting the mean sea level atmospheric pressure in accordance with ICAO standard atmosphere i.e. 1013', '[{"id": "a", "text": "millibars.", "correct": true}, {"id": "b", "text": "Setting an altimeter to read aerodrome altitude above sea level.", "correct": false}, {"id": "c", "text": "quite new equipment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aspect ratio of 8 : 1 would mean', '[{"id": "a", "text": "span 64, mean chord 8.", "correct": true}, {"id": "b", "text": "mean chord 64, span 8.", "correct": false}, {"id": "c", "text": "span squared 64, chord 8.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'QFE is', '[{"id": "a", "text": "airfield pressure.", "correct": true}, {"id": "b", "text": "difference between sea level and airfield pressure.", "correct": false}, {"id": "c", "text": "sea level pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'For any given speed, a decrease in aircraft weight, the induced drag will', '[{"id": "a", "text": "decrease.", "correct": true}, {"id": "b", "text": "remain the same.", "correct": false}, {"id": "c", "text": "increase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The amount of lift generated by a wing is', '[{"id": "a", "text": "greatest at the tip.", "correct": false}, {"id": "b", "text": "constant along the span.", "correct": false}, {"id": "c", "text": "greatest at the root.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Induced Drag is', '[{"id": "a", "text": "greatest towards the tip and downwash decreases from tip to root.", "correct": true}, {"id": "b", "text": "greatest towards the wing tip and downwash is greatest towards the root.", "correct": false}, {"id": "c", "text": "greatest towards the wing root and downwash is greatest at the tip.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Induced Drag is', '[{"id": "a", "text": "never equal to profile drag.", "correct": false}, {"id": "b", "text": "equal to profile drag at Vmd.", "correct": true}, {"id": "c", "text": "equal to profile drag at stalling angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With an increase in aircraft weight', '[{"id": "a", "text": "Vmd will be at a higher speed.", "correct": true}, {"id": "b", "text": "Vmd will be at the same speed.", "correct": false}, {"id": "c", "text": "Vmd will be at a lower speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'For a given IAS an increase in altitude will result in', '[{"id": "a", "text": "an increase in induced drag.", "correct": false}, {"id": "b", "text": "no change in the value of induced drag.", "correct": true}, {"id": "c", "text": "an increase in profile drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Stall inducers may be fitted to a wing', '[{"id": "a", "text": "at the root to cause the root to stall first.", "correct": true}, {"id": "b", "text": "at the tip to cause the root to stall first.", "correct": false}, {"id": "c", "text": "at the root to cause the tip to stall first.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The optimum angle of attack of an aerofoil is the angle at which', '[{"id": "a", "text": "the aerofoil produces maximum lift.", "correct": false}, {"id": "b", "text": "the aerofoil produces zero lift.", "correct": false}, {"id": "c", "text": "the highest lift/drag ratio is produced.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Minimum total drag of an aircraft occurs', '[{"id": "a", "text": "when induced drag is least.", "correct": false}, {"id": "b", "text": "at the stalling speed.", "correct": false}, {"id": "c", "text": "when profile drag equals induced drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the weight of an aircraft is increased, the induced drag at a given speed', '[{"id": "a", "text": "will increase.", "correct": true}, {"id": "b", "text": "will decrease.", "correct": false}, {"id": "c", "text": "will remain the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The transition point on a wing is the point where', '[{"id": "a", "text": "the boundary layer flow changes from laminar to turbulent.", "correct": true}, {"id": "b", "text": "the flow divides to pass above and below the wing.", "correct": false}, {"id": "c", "text": "the flow separates from the wing surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A laminar boundary layer will produce', '[{"id": "a", "text": "more skin friction drag than a turbulent one.", "correct": false}, {"id": "b", "text": "the same skin friction drag as a turbulent one.", "correct": false}, {"id": "c", "text": "less skin friction drag than a turbulent one.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The boundary layer is', '[{"id": "a", "text": "thickest at the leading edge.", "correct": false}, {"id": "b", "text": "thickest at the trailing edge.", "correct": true}, {"id": "c", "text": "constant thickness from leading to trailing edges.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The amount of thrust produced by a jet engine or a propeller can be calculated using', '[{"id": "a", "text": "Newton''s 3rd law.", "correct": false}, {"id": "b", "text": "Newton''s 2nd law.", "correct": true}, {"id": "c", "text": "Newton''s 1st law.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An engine which produces an efflux of high speed will be', '[{"id": "a", "text": "less efficient.", "correct": true}, {"id": "b", "text": "more efficient.", "correct": false}, {"id": "c", "text": "speed of efflux has no affect on the engine efficiency.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Wing loading is calculated by weight', '[{"id": "a", "text": "divided by lift.", "correct": false}, {"id": "b", "text": "divided by gross wing area.", "correct": true}, {"id": "c", "text": "multiplied by gross wing area.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Induced drag is', '[{"id": "a", "text": "nothing to do with speed.", "correct": false}, {"id": "b", "text": "proportional to speed.", "correct": false}, {"id": "c", "text": "inversely proportional to the square of speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the angle of attack increases the stagnation point', '[{"id": "a", "text": "moves towards the upper surface.", "correct": false}, {"id": "b", "text": "does not move.", "correct": false}, {"id": "c", "text": "moves towards the lower surface.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The term pitch-up is due to', '[{"id": "a", "text": "compressibility effect.", "correct": false}, {"id": "b", "text": "ground effect.", "correct": false}, {"id": "c", "text": "longitudinal instability.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In a steady climb at a steady IAS, the TAS is', '[{"id": "a", "text": "more than IAS.", "correct": true}, {"id": "b", "text": "the same.", "correct": false}, {"id": "c", "text": "less than IAS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An untapered straight wing will', '[{"id": "a", "text": "have no yaw effect in banking.", "correct": false}, {"id": "b", "text": "stall at the root first.", "correct": true}, {"id": "c", "text": "have no change in induced drag in the bank.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With the ailerons away from the neutral, induced drag is', '[{"id": "a", "text": "higher on the lower wing plus profile drag increases.", "correct": false}, {"id": "b", "text": "unchanged but profile drag is higher.", "correct": false}, {"id": "c", "text": "higher on the upper wing plus profile drag increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'All the lift can be said to act through the', '[{"id": "a", "text": "centre of pressure.", "correct": true}, {"id": "b", "text": "centre of gravity.", "correct": false}, {"id": "c", "text": "normal axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The concept of thrust is explained by', '[{"id": "a", "text": "Bernoulli''s theorem.", "correct": false}, {"id": "b", "text": "Newton''s 3rd law.", "correct": true}, {"id": "c", "text": "Newton''s 1st law.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The camber of an aerofoil section is', '[{"id": "a", "text": "the angle which the aerofoil makes with the relative airflow.", "correct": false}, {"id": "b", "text": "the curvature of the median line of the aerofoil.", "correct": true}, {"id": "c", "text": "the angle of incidence towards the tip of a wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As air flows over the upper cambered surface of an aerofoil, what happens to velocity and pressure?', '[{"id": "a", "text": "Velocity increases, pressure increases.", "correct": false}, {"id": "b", "text": "Velocity increases, pressure decreases.", "correct": true}, {"id": "c", "text": "Velocity decreases, pressure decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is the force that tends to pull an aircraft down towards the earth?', '[{"id": "a", "text": "Thrust.", "correct": false}, {"id": "b", "text": "Weight.", "correct": true}, {"id": "c", "text": "Drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The angle at which the chord line of the aerofoil is presented to the airflow is known as', '[{"id": "a", "text": "angle of attack.", "correct": true}, {"id": "b", "text": "resultant.", "correct": false}, {"id": "c", "text": "angle of incidence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The imaginary straight line which passes through an aerofoil section from leading edge to trailing edge is called', '[{"id": "a", "text": "the chord line.", "correct": true}, {"id": "b", "text": "the direction of relative airflow.", "correct": false}, {"id": "c", "text": "centre of pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is the angle between the chord line of the wing, and the longitudinal axis of the aircraft, known as?', '[{"id": "a", "text": "Angle of dihedral.", "correct": false}, {"id": "b", "text": "Angle of attack.", "correct": false}, {"id": "c", "text": "Angle of incidence.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Wing tip vortices create a type of drag known as', '[{"id": "a", "text": "form drag.", "correct": false}, {"id": "b", "text": "profile drag.", "correct": false}, {"id": "c", "text": "induced drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the angle of attack is increased (up to the stall point), which of the following is correct?', '[{"id": "a", "text": "Both are correct.", "correct": true}, {"id": "b", "text": "Pressure difference between top and bottom of the wing increases.", "correct": false}, {"id": "c", "text": "Lift increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What type of drag, depends on the smoothness of the body, and surface area over which the air flows?', '[{"id": "a", "text": "Form drag.", "correct": false}, {"id": "b", "text": "Parasite drag.", "correct": false}, {"id": "c", "text": "Skin friction drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When airflow velocity over an upper cambered surface of an aerofoil decreases, what takes place?', '[{"id": "a", "text": "Pressure decreases, lift increases.", "correct": false}, {"id": "b", "text": "Pressure increases, lift decreases.", "correct": true}, {"id": "c", "text": "Pressure increases, lift increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When an aircraft stalls', '[{"id": "a", "text": "lift increases and drag decreases.", "correct": false}, {"id": "b", "text": "lift and drag increase.", "correct": false}, {"id": "c", "text": "lift decreases and drag increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft wing with an aspect ration of 6:1 is proportional so that', '[{"id": "a", "text": "the wing area is six times the span.", "correct": false}, {"id": "b", "text": "the mean chord is six times the thickness.", "correct": false}, {"id": "c", "text": "the wing span is six times the mean chord.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Upward and outward inclination of a mainplane is termed', '[{"id": "a", "text": "dihedral.", "correct": true}, {"id": "b", "text": "sweep.", "correct": false}, {"id": "c", "text": "stagger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following forces act on an aircraft in level flight?', '[{"id": "a", "text": "Lift, drag, thrust.", "correct": false}, {"id": "b", "text": "Lift, thrust, and weight.", "correct": false}, {"id": "c", "text": "Lift, thrust, weight, and drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With reference to altimeters, QFE is', '[{"id": "a", "text": "the manufacturers registered name.", "correct": false}, {"id": "b", "text": "quite fine equipment.", "correct": false}, {"id": "c", "text": "setting aerodrome atmospheric pressure so that an altimeter reads zero on landing and take off.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Wing loading is', '[{"id": "a", "text": "WING AREA * WING CHORD.", "correct": false}, {"id": "b", "text": "GROSS WEIGHT divided by GROSS WING AREA.", "correct": true}, {"id": "c", "text": "the ultimate tensile strength of the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Weight is equal to', '[{"id": "a", "text": "mass * acceleration.", "correct": false}, {"id": "b", "text": "mass * gravity.", "correct": true}, {"id": "c", "text": "volume * gravity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Induced drag', '[{"id": "a", "text": "increases with increase in aircraft weight.", "correct": true}, {"id": "b", "text": "increases with an increase in speed.", "correct": false}, {"id": "c", "text": "reduces with an increase in angle of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Airflow over the upper surface of the wing generally', '[{"id": "a", "text": "flows towards the tip.", "correct": false}, {"id": "b", "text": "flows towards the root.", "correct": true}, {"id": "c", "text": "flows straight from leading edge to trailing edge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With an increase in aspect ratio for a given IAS, induced drag will', '[{"id": "a", "text": "reduce.", "correct": true}, {"id": "b", "text": "remain constant.", "correct": false}, {"id": "c", "text": "increase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the density of the air is increased, the lift will', '[{"id": "a", "text": "remain the same.", "correct": false}, {"id": "b", "text": "increase.", "correct": true}, {"id": "c", "text": "decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'All the factors that affect the lift produced by an aerofoil are', '[{"id": "a", "text": "angle of attack, velocity, wing area, aerofoil shape, air density.", "correct": true}, {"id": "b", "text": "angle of attack, air temperature, velocity, wing area.", "correct": false}, {"id": "c", "text": "angle of attack, air density, velocity, wing area.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A wing section suitable for high speed would be', '[{"id": "a", "text": "thin with high camber.", "correct": false}, {"id": "b", "text": "thick with high camber.", "correct": false}, {"id": "c", "text": "thin with little or no camber.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The induced drag of an aircraft', '[{"id": "a", "text": "increases if aspect ratio is increased.", "correct": false}, {"id": "b", "text": "decreases with increasing speed.", "correct": true}, {"id": "c", "text": "increases with increasing speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the speed of an aircraft increases, the profile drag', '[{"id": "a", "text": "decreases at first then increase.", "correct": false}, {"id": "b", "text": "increases.", "correct": true}, {"id": "c", "text": "decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The stagnation point on an aerofoil is the point where', '[{"id": "a", "text": "the boundary layer changes from laminar to turbulent.", "correct": false}, {"id": "b", "text": "the suction pressure reaches a maximum.", "correct": false}, {"id": "c", "text": "the airflow is brought completely to rest.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The stalling of an aerofoil is affected by the', '[{"id": "a", "text": "transition speed.", "correct": false}, {"id": "b", "text": "airspeed.", "correct": false}, {"id": "c", "text": "angle of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The most fuel efficient of the following types of engine is the', '[{"id": "a", "text": "turbo-jet engine.", "correct": false}, {"id": "b", "text": "turbo-fan engine.", "correct": true}, {"id": "c", "text": "rocket.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The quietest of the following types of engine is the', '[{"id": "a", "text": "turbo-jet engine.", "correct": false}, {"id": "b", "text": "rocket.", "correct": false}, {"id": "c", "text": "turbo-fan engine.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Forward motion of a glider is provided by', '[{"id": "a", "text": "the weight.", "correct": true}, {"id": "b", "text": "the drag.", "correct": false}, {"id": "c", "text": "the engine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Profile drag consists of what drag types?', '[{"id": "a", "text": "Form, induced and interference.", "correct": false}, {"id": "b", "text": "Form, induced and skin friction.", "correct": false}, {"id": "c", "text": "Form, skin friction and interference.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft in straight and level flight is subject to', '[{"id": "a", "text": "a load factor of 1.", "correct": true}, {"id": "b", "text": "a load factor of ½.", "correct": false}, {"id": "c", "text": "zero load factor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Aspect ratio is given by the formula:', '[{"id": "a", "text": "Mean Chord / Span.", "correct": false}, {"id": "b", "text": "Span^2 / Area.", "correct": true}, {"id": "c", "text": "Span^2 / Mean Chord.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aspect ratio of 8 means', '[{"id": "a", "text": "the mean chord is 8 times the span.", "correct": false}, {"id": "b", "text": "the span is 8 times the mean chord.", "correct": true}, {"id": "c", "text": "the area is 8 times the span.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A high aspect ratio wing', '[{"id": "a", "text": "has a higher stall angle than a low aspect ratio wing.", "correct": false}, {"id": "b", "text": "is stiffer than a low aspect ratio wing.", "correct": false}, {"id": "c", "text": "has less induced drag than a low aspect ratio wing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Induced downwash', '[{"id": "a", "text": "reduces the effective angle of attack of the wing.", "correct": true}, {"id": "b", "text": "increases the effective angle of attack of the wing.", "correct": false}, {"id": "c", "text": "has no effect on the angle of attack of the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Given 2 wings, the first with a span of 12m and a chord of 2 m. The second has a span of 6m and a chord of 1m. How do their Aspect Ratios compare?', '[{"id": "a", "text": "The first is higher.", "correct": false}, {"id": "b", "text": "They are the same.", "correct": true}, {"id": "c", "text": "The second is higher.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The C of G moves in flight. The most likely cause of this is', '[{"id": "a", "text": "movement of passengers.", "correct": false}, {"id": "b", "text": "consumption of fuel and oils.", "correct": true}, {"id": "c", "text": "movement of cargo.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A straight rectangular wing, without any twist, will', '[{"id": "a", "text": "stall equally along the span of the wing.", "correct": false}, {"id": "b", "text": "stall first at the tip.", "correct": false}, {"id": "c", "text": "stall first at the root.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Aspect ratio of a wing is defined as the ratio of the', '[{"id": "a", "text": "wingspan to the mean chord.", "correct": true}, {"id": "b", "text": "wingspan to the wing root.", "correct": false}, {"id": "c", "text": "square of the chord to the wingspan.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following is true?', '[{"id": "a", "text": "Lift acts at right angles to the relative airflow and weight acts vertically down.", "correct": true}, {"id": "b", "text": "Lift acts at right angles to the wing chord line and weight acts vertically down.", "correct": false}, {"id": "c", "text": "Lift acts at right angles to the relative air flow and weight acts at right angles to the aircraft centre line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The airflow over the upper surface of a cambered wing', '[{"id": "a", "text": "increases in velocity and reduces in pressure.", "correct": true}, {"id": "b", "text": "increases in velocity and pressure.", "correct": false}, {"id": "c", "text": "reduces in velocity and increases in pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With increased speed in level flight', '[{"id": "a", "text": "profile drag increases.", "correct": true}, {"id": "b", "text": "induced drag increases.", "correct": false}, {"id": "c", "text": "profile drag remains constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The angle of attack of an aerofoil section is the angle between the', '[{"id": "a", "text": "underside of the wing surface and the mean airflow.", "correct": false}, {"id": "b", "text": "chord line and the relative airflow.", "correct": true}, {"id": "c", "text": "chord line and the centre line of the fuselage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A swept wing tends to stall first at the', '[{"id": "a", "text": "centre section.", "correct": false}, {"id": "b", "text": "root.", "correct": false}, {"id": "c", "text": "tip.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The trailing vortex on a pointed wing (taper ratio = 0) is', '[{"id": "a", "text": "at the tip.", "correct": false}, {"id": "b", "text": "equally all along the wing span.", "correct": true}, {"id": "c", "text": "at the root.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The lift curve for a delta wing is', '[{"id": "a", "text": "more steep than that of a high aspect ratio wing.", "correct": false}, {"id": "b", "text": "less steep than that of a high aspect ratio wing.", "correct": true}, {"id": "c", "text": "the same as that of a high aspect ratio wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A delta wing has', '[{"id": "a", "text": "a lower stall angle than a straight wing.", "correct": false}, {"id": "b", "text": "a higher stall angle than a straight wing.", "correct": true}, {"id": "c", "text": "the same stall angle than a straight wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The speed of air over a swept wing which contributes to the lift is', '[{"id": "a", "text": "less than the aircraft speed.", "correct": true}, {"id": "b", "text": "the same as the aircraft speed.", "correct": false}, {"id": "c", "text": "more than the aircraft speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'For a given angle of attack, induced drag is', '[{"id": "a", "text": "greater on a high aspect ratio wing.", "correct": false}, {"id": "b", "text": "greater towards the wing root.", "correct": false}, {"id": "c", "text": "greater on a low aspect ratio wing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In straight and level flight, the angle of attack of a swept wing is', '[{"id": "a", "text": "less than the aircraft angle to the horizontal.", "correct": false}, {"id": "b", "text": "more than the aircraft angle to the horizontal.", "correct": true}, {"id": "c", "text": "the same as the aircraft angle to the horizontal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Induced drag', '[{"id": "a", "text": "is equal to the profile drag at Vmd.", "correct": true}, {"id": "b", "text": "is equal to the profile drag at the stalling speed.", "correct": false}, {"id": "c", "text": "is never equal to the profile drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A delta wing aircraft flying at the same speed (subsonic) and angle of attack as a swept wing aircraft of similar wing area will produce', '[{"id": "a", "text": "more lift.", "correct": false}, {"id": "b", "text": "less lift.", "correct": true}, {"id": "c", "text": "the same lift.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The stagnation point is', '[{"id": "a", "text": "static pressure minus dynamic pressure.", "correct": false}, {"id": "b", "text": "dynamic pressure only.", "correct": false}, {"id": "c", "text": "static pressure plus dynamic pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a swept wing aircraft, due to the adverse pressure gradient, the boundary layer on the upper surface of the wing tends to flow', '[{"id": "a", "text": "towards the root.", "correct": false}, {"id": "b", "text": "towards the tip.", "correct": true}, {"id": "c", "text": "directly from leading edge to trailing edge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With increased speed in level flight', '[{"id": "a", "text": "induced drag increases.", "correct": false}, {"id": "b", "text": "profile drag increases.", "correct": true}, {"id": "c", "text": "profile drag remains constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If a swept wing stalls at the tips first, the aircraft will', '[{"id": "a", "text": "pitch nose up.", "correct": true}, {"id": "b", "text": "roll.", "correct": false}, {"id": "c", "text": "pitch nose down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The thickness/chord ratio of the wing is also known as', '[{"id": "a", "text": "fineness ratio.", "correct": true}, {"id": "b", "text": "mean chord ratio.", "correct": false}, {"id": "c", "text": "aspect ratio.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Flexure of a rearward swept wing will', '[{"id": "a", "text": "increase the lift and hence increase the flexure.", "correct": false}, {"id": "b", "text": "increase the lift and hence decrease the flexure.", "correct": false}, {"id": "c", "text": "decrease the lift and hence decrease the flexure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A High Aspect Ratio wing is a wing with', '[{"id": "a", "text": "short span, long chord.", "correct": false}, {"id": "b", "text": "long span, long chord.", "correct": false}, {"id": "c", "text": "long span, short chord.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Stall commencing at the root is preferred because', '[{"id": "a", "text": "it provides the pilot with a warning of complete loss of lift.", "correct": true}, {"id": "b", "text": "the ailerons become ineffective.", "correct": false}, {"id": "c", "text": "it will cause the aircraft to pitch nose up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the angle of attack of a wing is increased in flight, the', '[{"id": "a", "text": "CofP will move aft.", "correct": false}, {"id": "b", "text": "CofP will move forward.", "correct": true}, {"id": "c", "text": "C of G will move aft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The Rams Horn Vortex on a forward swept wing will be', '[{"id": "a", "text": "more than a rearward swept wing.", "correct": false}, {"id": "b", "text": "less than a rearward swept wing.", "correct": true}, {"id": "c", "text": "the same as a rearward swept wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'For a cambered wing section the zero lift angle of attack will be', '[{"id": "a", "text": "4 degrees.", "correct": false}, {"id": "b", "text": "zero.", "correct": false}, {"id": "c", "text": "negative.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Airflow at subsonic speed is taken to be', '[{"id": "a", "text": "compressible.", "correct": false}, {"id": "b", "text": "either a or b depending on altitude.", "correct": false}, {"id": "c", "text": "incompressible.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If fluid flow through a venturi is said to be incompressible, the speed of the flow increases at the throat to', '[{"id": "a", "text": "allow for a reduction in static pressure.", "correct": false}, {"id": "b", "text": "maintain a constant volume flow rate.", "correct": true}, {"id": "c", "text": "allow for an increase in static pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'To produce lift, an aerofoil must be', '[{"id": "a", "text": "asymmetrical.", "correct": false}, {"id": "b", "text": "symmetrical.", "correct": false}, {"id": "c", "text": "either symmetrical or asymmetrical.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lift is dependent on', '[{"id": "a", "text": "the net area of the wing ,the density of the fluid medium and the velocity.", "correct": false}, {"id": "b", "text": "the area of the wing, the density of the fluid medium, and the square of the velocity.", "correct": true}, {"id": "c", "text": "the frontal area of the wing, the density of the fluid medium and the velocity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A wing develops 10,000 N of lift at 100 knots. Assuming the wing remains at the same angle of attack and remains at the same altitude, how much lift will it develop at 300knots?', '[{"id": "a", "text": "30,000 N.", "correct": false}, {"id": "b", "text": "900,000 N.", "correct": false}, {"id": "c", "text": "90,000 N.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The angle of attack is', '[{"id": "a", "text": "related to angle of incidence.", "correct": true}, {"id": "b", "text": "always kept below 15 degrees.", "correct": false}, {"id": "c", "text": "not related to the angle of incidence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The difference between the mean camber line and the chord line of an aerofoil is', '[{"id": "a", "text": "neither are straight.", "correct": false}, {"id": "b", "text": "they both may be curved.", "correct": false}, {"id": "c", "text": "one is always straight and the other may be straight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the C of G is calculated after loading as within limits for take off', '[{"id": "a", "text": "a further calculation is required prior to landing to allow for fuel and oil consumption.", "correct": true}, {"id": "b", "text": "a further calculation is required prior to landing to allow for flap deployment.", "correct": false}, {"id": "c", "text": "no further calculation is required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The span wise component of the airflow is', '[{"id": "a", "text": "greater at higher speeds.", "correct": false}, {"id": "b", "text": "unaffected by speed.", "correct": false}, {"id": "c", "text": "less at higher speeds.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A wing fence', '[{"id": "a", "text": "acts as a lift dumping device.", "correct": false}, {"id": "b", "text": "reduces span wise flow on a swept wing thus reducing induced drag.", "correct": true}, {"id": "c", "text": "increases lateral control.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With all conditions remaining the same, if the aircraft speed is halved, by what factor is the lift reduced?', '[{"id": "a", "text": "Half.", "correct": false}, {"id": "b", "text": "By a factor of 4.", "correct": true}, {"id": "c", "text": "Remains the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The boundary layer over an aerofoil is', '[{"id": "a", "text": "a layer of air close to the aerofoil which is moving at a velocity less than free stream air.", "correct": true}, {"id": "b", "text": "a layer of turbulent air close to the aerofoil which is moving at a velocity less than free stream air.", "correct": false}, {"id": "c", "text": "a layer of air close to the aerofoil that is stationary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a swept wing aircraft, the fineness ratio of an aerofoil is', '[{"id": "a", "text": "highest at the root.", "correct": false}, {"id": "b", "text": "equal throughout the span.", "correct": false}, {"id": "c", "text": "highest at the tip.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Streamlining will reduce', '[{"id": "a", "text": "induced drag.", "correct": false}, {"id": "b", "text": "skin friction drag.", "correct": false}, {"id": "c", "text": "form drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft has a gross weight of 3000 kg and is then subjected to a total weight of 6000 kg the load factor will be', '[{"id": "a", "text": "2G.", "correct": true}, {"id": "b", "text": "9G.", "correct": false}, {"id": "c", "text": "3G.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Ice formed on the leading edge will cause the aircraft to', '[{"id": "a", "text": "stall at a higher speed.", "correct": true}, {"id": "b", "text": "stall at a lower speed.", "correct": false}, {"id": "c", "text": "stall at the same stall speed and AOA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Under what conditions will an aircraft create best lift?', '[{"id": "a", "text": "Hot damp day at 1200 ft.", "correct": false}, {"id": "b", "text": "Cold dry day at 200 ft.", "correct": true}, {"id": "c", "text": "Cold wet day at 1200 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As Mach number increases, what is the effect on boundary layer?', '[{"id": "a", "text": "Becomes more turbulent.", "correct": true}, {"id": "b", "text": "Decreases in thickness.", "correct": false}, {"id": "c", "text": "Becomes less turbulent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'During a glide the following forces act on an aircraft', '[{"id": "a", "text": "lift and weight only.", "correct": false}, {"id": "b", "text": "lift, drag, weight.", "correct": true}, {"id": "c", "text": "lift, weight, thrust.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aileron is moved downward', '[{"id": "a", "text": "the stalling angle of that wing is increased.", "correct": false}, {"id": "b", "text": "the stalling angle is not affected but the stalling speed is decreased.", "correct": false}, {"id": "c", "text": "the stalling angle of that wing is decreased.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the wing loading of an aircraft were reduced the stalling speed would', '[{"id": "a", "text": "increase.", "correct": false}, {"id": "b", "text": "not be affected.", "correct": false}, {"id": "c", "text": "decrease.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The lift on a wing is increased with', '[{"id": "a", "text": "an increase in temperature.", "correct": false}, {"id": "b", "text": "an increase in pressure.", "correct": true}, {"id": "c", "text": "an increase in humidity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The airflow behind a normal shockwave will', '[{"id": "a", "text": "always be subsonic and in the same direction as the original airflow.", "correct": true}, {"id": "b", "text": "always be supersonic and in the same direction as the original airflow.", "correct": false}, {"id": "c", "text": "always be subsonic and deflected from the direction of the original airflow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Induced drag can be reduced by the use of', '[{"id": "a", "text": "streamlining.", "correct": false}, {"id": "b", "text": "high aspect ratio wings.", "correct": true}, {"id": "c", "text": "fairings at junctions between fuselage and wings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Interference drag can be reduced by the use of', '[{"id": "a", "text": "fairings at junctions between fuselage and wings.", "correct": true}, {"id": "b", "text": "high aspect ratio wings.", "correct": false}, {"id": "c", "text": "streamlining.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Gliding angle is the angle between', '[{"id": "a", "text": "ground and the glide path.", "correct": true}, {"id": "b", "text": "aircraft and flight path.", "correct": false}, {"id": "c", "text": "aircraft and airflow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lift is generated by a wing', '[{"id": "a", "text": "mostly on the bottom surface.", "correct": false}, {"id": "b", "text": "mostly on the top surface.", "correct": true}, {"id": "c", "text": "equally on the top and bottom surfaces.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lift is dependent on', '[{"id": "a", "text": "the area of the wing, the density of the fluid medium and the square of the velocity.", "correct": true}, {"id": "b", "text": "the net area of the wing, the density of the fluid medium and the velocity.", "correct": false}, {"id": "c", "text": "the frontal area of the wing, the density of the fluid medium and the velocity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'To produce lift, an aerofoil must be', '[{"id": "a", "text": "symmetrical.", "correct": false}, {"id": "b", "text": "asymmetrical.", "correct": false}, {"id": "c", "text": "either symmetrical or asymmetrical.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Airflow at sub-sonic speed is taken to be', '[{"id": "a", "text": "incompressible.", "correct": true}, {"id": "b", "text": "compressible.", "correct": false}, {"id": "c", "text": "either (a) or (b) depending on altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The total drag of an aircraft', '[{"id": "a", "text": "changes with speed.", "correct": true}, {"id": "b", "text": "increases with speed.", "correct": false}, {"id": "c", "text": "increases with the square of speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), '_______ angle of attack is known as optimum angle of attack.', '[{"id": "a", "text": "5 to 7 degrees.", "correct": false}, {"id": "b", "text": "3 to 4 degrees.", "correct": true}, {"id": "c", "text": "10 to 12 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Induced drag is ________ at root.', '[{"id": "a", "text": "lowest.", "correct": true}, {"id": "b", "text": "greatest.", "correct": false}, {"id": "c", "text": "neutral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Profile drag is _______ to speed.', '[{"id": "a", "text": "neutral.", "correct": false}, {"id": "b", "text": "inversely proportional.", "correct": false}, {"id": "c", "text": "proportional.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A shock stall occurs at', '[{"id": "a", "text": "large angles of attack.", "correct": false}, {"id": "b", "text": "small angles of attack.", "correct": true}, {"id": "c", "text": "equally both large and small angles of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What happens to the wingtip stagnation point as the AOA increases?', '[{"id": "a", "text": "It moves down and under the leading edge.", "correct": true}, {"id": "b", "text": "It moves up and over the leading edge.", "correct": false}, {"id": "c", "text": "It remains unchanged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The point at which airflow ceases to be laminar and becomes turbulent is the', '[{"id": "a", "text": "boundary point.", "correct": false}, {"id": "b", "text": "transition point.", "correct": true}, {"id": "c", "text": "separation point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following is true about Profile drag?', '[{"id": "a", "text": "Profile drag = Skin Drag + Form Drag.", "correct": true}, {"id": "b", "text": "Profile drag = skin drag + induced drag.", "correct": false}, {"id": "c", "text": "Profile drag = induced drag + Form drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which statement is true?', '[{"id": "a", "text": "Profile drag increases with the square of the airspeed.", "correct": true}, {"id": "b", "text": "Both Induced drag and profile drag increase with the square of the airspeed.", "correct": false}, {"id": "c", "text": "Induced drag increases with the square of the airspeed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which statement is true?', '[{"id": "a", "text": "Rectangular wings stall at the root first.", "correct": true}, {"id": "b", "text": "Both tapered and rectangular wings will stall at the tip first.", "correct": false}, {"id": "c", "text": "Tapered wings stall at the root first.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'During inverted level flight an aircraft accelerometer shows', '[{"id": "a", "text": "-2g.", "correct": false}, {"id": "b", "text": "-1g.", "correct": true}, {"id": "c", "text": "0g.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'During straight and level flight an aircraft accelerometer shows', '[{"id": "a", "text": "4g.", "correct": false}, {"id": "b", "text": "1g.", "correct": true}, {"id": "c", "text": "2g.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following is incorrect about induced drag?', '[{"id": "a", "text": "It will increase inversely to the square of the airspeed.", "correct": false}, {"id": "b", "text": "It will decrease in proportion to the square of the airspeed.", "correct": false}, {"id": "c", "text": "It will increase when the angle of attack is reduced.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What produces the most lift at low speeds?', '[{"id": "a", "text": "High camber.", "correct": true}, {"id": "b", "text": "Low aspect ratio.", "correct": false}, {"id": "c", "text": "High aspect ratio.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the angle of attack is zero, but lift is produced, the', '[{"id": "a", "text": "wing is symmetrical.", "correct": false}, {"id": "b", "text": "wing is cambered.", "correct": true}, {"id": "c", "text": "wing has positive angle of incidence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When is the angle of incidence the same as the angle of attack?', '[{"id": "a", "text": "Never.", "correct": false}, {"id": "b", "text": "In descent.", "correct": false}, {"id": "c", "text": "When relative airflow is parallel to longitudinal axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Flaps at landing position', '[{"id": "a", "text": "decrease landing speed.", "correct": true}, {"id": "b", "text": "decrease take off and landing speeds.", "correct": false}, {"id": "c", "text": "decrease take off speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As a subsonic aircraft speeds-up, its Centre of Pressure', '[{"id": "a", "text": "moves aft.", "correct": true}, {"id": "b", "text": "moves forward.", "correct": false}, {"id": "c", "text": "is unaffected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lowering of the flaps', '[{"id": "a", "text": "increases drag.", "correct": false}, {"id": "b", "text": "increases lift.", "correct": false}, {"id": "c", "text": "increases drag and lift.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Wing spoilers, when used asymmetrically, are associated with', '[{"id": "a", "text": "rudder.", "correct": false}, {"id": "b", "text": "elevators.", "correct": false}, {"id": "c", "text": "ailerons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What do ruddervators do?', '[{"id": "a", "text": "Control yaw and roll.", "correct": false}, {"id": "b", "text": "Control pitch and yaw.", "correct": true}, {"id": "c", "text": "Control pitch and roll.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What controls pitch and roll on a delta wing aircraft?', '[{"id": "a", "text": "Ailerons.", "correct": false}, {"id": "b", "text": "Elevons.", "correct": true}, {"id": "c", "text": "Elevators.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What does a trim tab do?', '[{"id": "a", "text": "Allows the C of G to be outside the normal limit.", "correct": false}, {"id": "b", "text": "Provides finer control movements by the pilot.", "correct": false}, {"id": "c", "text": "Eases control loading for pilot.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'How does a balance tab move?', '[{"id": "a", "text": "In the same direction a small amount.", "correct": false}, {"id": "b", "text": "In the opposite direction proportional to the control surface it is attached to.", "correct": true}, {"id": "c", "text": "In the same direction proportional to the control surface it is attached to.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft is yawing to the left, where would you position the trim tab on the rudder?', '[{"id": "a", "text": "To the centre.", "correct": false}, {"id": "b", "text": "To the left.", "correct": true}, {"id": "c", "text": "To the right.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft is flying with a left wing low, where would you move the left aileron trim tab?', '[{"id": "a", "text": "Down.", "correct": false}, {"id": "b", "text": "Up.", "correct": true}, {"id": "c", "text": "Moving the aileron trim tab will not correct the situation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When a leading edge flap is fully extended, what is the slot in the wing for?', '[{"id": "a", "text": "To re-energise the boundary layer.", "correct": true}, {"id": "b", "text": "To increase the lift.", "correct": false}, {"id": "c", "text": "To allow the flap to retract into it when it retracts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With respect to differential aileron control, which of the following is true?', '[{"id": "a", "text": "The up going and down going ailerons both deflect to the same angle.", "correct": false}, {"id": "b", "text": "The up going Aileron moves through a smaller angle than the down going aileron.", "correct": false}, {"id": "c", "text": "The down going aileron moves through a smaller angle than the up going aileron.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The aeroplane fin is of symmetrical aerofoil section and will therefore provide a side-load', '[{"id": "a", "text": "only when the rudder is moved.", "correct": false}, {"id": "b", "text": "if a suitable angle of attack develops due either yaw or rudder movement.", "correct": true}, {"id": "c", "text": "only if a suitable angle of attack develops due to yaw.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft left wing is flying low. The aileron trimmer control to the left aileron trim tab in the cockpit would be', '[{"id": "a", "text": "moved up causing the left aileron to move up.", "correct": false}, {"id": "b", "text": "moved up causing the left aileron to move down.", "correct": true}, {"id": "c", "text": "moved down causing the left aileron to move down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An elevator tab moves down', '[{"id": "a", "text": "to make the nose go down.", "correct": false}, {"id": "b", "text": "to counteract for the aircraft flying nose heavy.", "correct": true}, {"id": "c", "text": "to counteract for the aircraft flying tail heavy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The stall margin is controlled by', '[{"id": "a", "text": "speed bug cursor.", "correct": false}, {"id": "b", "text": "EPR limits.", "correct": false}, {"id": "c", "text": "angle of attack and flap position.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Other than spoilers, where are speed brakes located?', '[{"id": "a", "text": "Under the Fuselage.", "correct": false}, {"id": "b", "text": "Either side of the Fuselage.", "correct": true}, {"id": "c", "text": "On the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With a trailing edge flap being lowered, due to rising gusts, what will happen to the angle of attack?', '[{"id": "a", "text": "Tend to decrease.", "correct": false}, {"id": "b", "text": "Stay the same.", "correct": false}, {"id": "c", "text": "Tend to increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A device used do dump lift from an aircraft is', '[{"id": "a", "text": "leading edge flaps.", "correct": false}, {"id": "b", "text": "trailing edge flaps.", "correct": false}, {"id": "c", "text": "spoiler.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The purpose of a slot in a wing is to', '[{"id": "a", "text": "provide housing for the slat.", "correct": false}, {"id": "b", "text": "speed up the airflow and increase lift.", "correct": false}, {"id": "c", "text": "act as venturi, accelerate the air and re-energise boundary layer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Large flap deployment', '[{"id": "a", "text": "causes increased span wise flow towards tips on wing upper surface.", "correct": true}, {"id": "b", "text": "causes increased span wise flow towards tips on wing lower surface.", "correct": false}, {"id": "c", "text": "has no effect on span wise flow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which part of the wing of a swept-wing aircraft stalls first?', '[{"id": "a", "text": "Tip stalls first.", "correct": true}, {"id": "b", "text": "Both stall together.", "correct": false}, {"id": "c", "text": "Root stalls first.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'During flight, an aircraft is yawing to the right. The aircraft would have a tendency to fly', '[{"id": "a", "text": "right wing low.", "correct": true}, {"id": "b", "text": "left wing low.", "correct": false}, {"id": "c", "text": "nose up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In the reversed camber horizontal stabilizer', '[{"id": "a", "text": "there is an increased tail plane up-force.", "correct": false}, {"id": "b", "text": "the elevator causes tail down movement i.e. increased tail plane down force.", "correct": false}, {"id": "c", "text": "there is an increased tailplane down-force.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When the trailing edge flap is extended', '[{"id": "a", "text": "CP moves rearward.", "correct": true}, {"id": "b", "text": "the CP moves forward but the CG does not change.", "correct": false}, {"id": "c", "text": "the CP moves forward and the pitching moment changes to nose up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With a drop in ambient temperature, an aircraft service ceiling will', '[{"id": "a", "text": "rise.", "correct": true}, {"id": "b", "text": "not be affected.", "correct": false}, {"id": "c", "text": "lower.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Servo tabs', '[{"id": "a", "text": "enable the pilot to bring the control surface back to neutral.", "correct": false}, {"id": "b", "text": "move in such a way as to help move the control surface.", "correct": true}, {"id": "c", "text": "provide artificial feel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Spring Tabs', '[{"id": "a", "text": "provide artificial feel.", "correct": false}, {"id": "b", "text": "enable the pilot to bring the control surface back to neutral.", "correct": false}, {"id": "c", "text": "move in such a way as to help move the control surface.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Extending a leading edge slat will have what effect on the angle of attack of a wing?', '[{"id": "a", "text": "Increase the angle of attack.", "correct": true}, {"id": "b", "text": "Decrease the angle of attack.", "correct": false}, {"id": "c", "text": "No effect on angle of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'To ensure that a wing stalls at the root first, stall wedges are', '[{"id": "a", "text": "installed on the wing leading edge at the wing root.", "correct": true}, {"id": "b", "text": "installed on the wing leading edge at the wing tip.", "correct": false}, {"id": "c", "text": "installed at the wing trailing edge at the wing root.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Krueger flaps make up part of the', '[{"id": "a", "text": "wing lower surface leading edge.", "correct": true}, {"id": "b", "text": "wing lower surface trailing edge.", "correct": false}, {"id": "c", "text": "wing upper surface leading edge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In a turn, wing spoilers may be deployed', '[{"id": "a", "text": "to assist the up going aileron.", "correct": true}, {"id": "b", "text": "in unison with both the up going and down going ailerons.", "correct": false}, {"id": "c", "text": "to act as an airbrake, interacting with the ailerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Dutch roll is movement in', '[{"id": "a", "text": "pitch and roll.", "correct": false}, {"id": "b", "text": "yaw and roll.", "correct": true}, {"id": "c", "text": "yaw and pitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is the main purpose of a frise aileron?', '[{"id": "a", "text": "Help pilot overcome aerodynamic loads.", "correct": false}, {"id": "b", "text": "Decrease drag on the up going wing.", "correct": false}, {"id": "c", "text": "Increase drag on the up going wing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Flap asymmetry causes the aircraft to', '[{"id": "a", "text": "nose down.", "correct": false}, {"id": "b", "text": "go one wing down.", "correct": true}, {"id": "c", "text": "nose up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft moves in yaw, what axis is it moving about?', '[{"id": "a", "text": "Longitudinal.", "correct": false}, {"id": "b", "text": "Lateral.", "correct": false}, {"id": "c", "text": "Normal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft is aerodynamically stable', '[{"id": "a", "text": "aircraft returns to trimmed attitude.", "correct": true}, {"id": "b", "text": "CofP moves back.", "correct": false}, {"id": "c", "text": "aircraft becomes too sensitive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What are ground spoilers used for?', '[{"id": "a", "text": "To assist the aircraft coming to a stop.", "correct": false}, {"id": "b", "text": "To slow the aircraft.", "correct": false}, {"id": "c", "text": "To dump lift.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Mass balance weights are used to', '[{"id": "a", "text": "balance the trailing edge of flying control surfaces.", "correct": false}, {"id": "b", "text": "counteract flutter on control surfaces.", "correct": true}, {"id": "c", "text": "balance the tabs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is a slot used for?', '[{"id": "a", "text": "Increased angle of attack during approach.", "correct": false}, {"id": "b", "text": "Increase the speed of the airflow.", "correct": false}, {"id": "c", "text": "To reinforce the boundary layer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Angle of Attack is the angle between chord', '[{"id": "a", "text": "relative air flow.", "correct": true}, {"id": "b", "text": "horizontal axis.", "correct": false}, {"id": "c", "text": "tip path plane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A high lift device is used for', '[{"id": "a", "text": "take-off only.", "correct": false}, {"id": "b", "text": "take-off and landing.", "correct": true}, {"id": "c", "text": "landing only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'How is a spoiler interconnected to other flight control systems?', '[{"id": "a", "text": "Spoiler to elevator.", "correct": false}, {"id": "b", "text": "Spoiler to aileron.", "correct": true}, {"id": "c", "text": "Spoiler to flap.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is aileron droop?', '[{"id": "a", "text": "The droop of ailerons with no hydraulics on.", "correct": true}, {"id": "b", "text": "The leading edge of both ailerons presented to the airflow.", "correct": false}, {"id": "c", "text": "One aileron lowered.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Earths atmosphere is', '[{"id": "a", "text": "3/5 oxygen, 2/5 nitrogen.", "correct": false}, {"id": "b", "text": "4/5 oxygen, 1/5 nitrogen.", "correct": false}, {"id": "c", "text": "1/5 oxygen, 4/5 nitrogen.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An anti-balance tab is used', '[{"id": "a", "text": "to relieve stick loads.", "correct": false}, {"id": "b", "text": "for trimming the aircraft.", "correct": false}, {"id": "c", "text": "to give more feel to the controls.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The fin helps to give', '[{"id": "a", "text": "directional stability about the normal axis.", "correct": true}, {"id": "b", "text": "directional stability about the longitudinal axis.", "correct": false}, {"id": "c", "text": "longitudinal stability about the normal axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft moves in roll, it is moving about the', '[{"id": "a", "text": "longitudinal axis.", "correct": true}, {"id": "b", "text": "normal axis.", "correct": false}, {"id": "c", "text": "lateral axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What effect does lowering the flaps for take-off have?', '[{"id": "a", "text": "Increases lift & reduces drag.", "correct": false}, {"id": "b", "text": "Increases lift and drag.", "correct": true}, {"id": "c", "text": "Increase lift only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What effect does lowering flaps for takeoff have?', '[{"id": "a", "text": "Reduces takeoff speeds only.", "correct": true}, {"id": "b", "text": "Reduces landing speeds only.", "correct": false}, {"id": "c", "text": "Reduces takeoff and landing speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When the flaps are lowered', '[{"id": "a", "text": "the lift vector moves rearward.", "correct": true}, {"id": "b", "text": "there is no effect on the lift vector.", "correct": false}, {"id": "c", "text": "the lift vector moves forward.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At take-off, if the flaps are lowered there is a', '[{"id": "a", "text": "large increase in lift and drag.", "correct": false}, {"id": "b", "text": "large increase in lift and small increase in drag.", "correct": true}, {"id": "c", "text": "small increase in lift and drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Wing spoilers can be used', '[{"id": "a", "text": "as ground spoilers on landing.", "correct": true}, {"id": "b", "text": "to assist the respective down going aileron in a turn.", "correct": false}, {"id": "c", "text": "to assist the elevators.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Differential aileron control will', '[{"id": "a", "text": "cause a nose down moment.", "correct": false}, {"id": "b", "text": "prevent yawing in conjunction with rudder input.", "correct": true}, {"id": "c", "text": "cause a nose up moment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Dutch Roll affects', '[{"id": "a", "text": "pitch and yaw simultaneously.", "correct": false}, {"id": "b", "text": "yaw and roll simultaneously.", "correct": true}, {"id": "c", "text": "pitch and roll simultaneously.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following are primary control surfaces?', '[{"id": "a", "text": "Elevators, ailerons, rudder.", "correct": true}, {"id": "b", "text": "Roll spoilers, elevators, tabs.", "correct": false}, {"id": "c", "text": "Elevators, roll spoilers, tabs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An anti-servo tab', '[{"id": "a", "text": "assists the pilot to move the controls back to neutral.", "correct": false}, {"id": "b", "text": "moves in the opposite direction to the control surface to assist the pilot.", "correct": false}, {"id": "c", "text": "moves in the same direction as the control surface to assist the pilot.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Slats', '[{"id": "a", "text": "keep the boundary layer from separating for longer.", "correct": true}, {"id": "b", "text": "increase the overall surface area and lift effect of wing.", "correct": false}, {"id": "c", "text": "act as an air brake.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Due to the change of lift forces resulting from the extension of flaps in flight', '[{"id": "a", "text": "nose should be lowered, reducing AOA.", "correct": true}, {"id": "b", "text": "nose should be raised, increasing AOA.", "correct": false}, {"id": "c", "text": "nose should remain in the same position, maintaining same AOA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Flight spoilers', '[{"id": "a", "text": "can be deployed on the down going wing in a turn to increase lift on that wing.", "correct": false}, {"id": "b", "text": "can be used to decrease lift to allow controlled decent without reduction of airspeed.", "correct": true}, {"id": "c", "text": "can be used with differential ailerons to reduce adverse yaw in a turn.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the aircraft is flying nose heavy, which direction would you move the elevator trim tab?', '[{"id": "a", "text": "Up to move elevator down.", "correct": false}, {"id": "b", "text": "Up to move elevator up.", "correct": false}, {"id": "c", "text": "Down to move elevator up.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Wing tip vortices are strongest when', '[{"id": "a", "text": "flying high speed straight and level flight.", "correct": false}, {"id": "b", "text": "flying into a headwind.", "correct": false}, {"id": "c", "text": "flying slowly at high angles of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Aerodynamic balance', '[{"id": "a", "text": "will reduce aerodynamic loading.", "correct": true}, {"id": "b", "text": "will cause CP to move forward of hinge and cause overbalance.", "correct": false}, {"id": "c", "text": "will cause CP to move towards the trailing edge and cause instability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A balance tab', '[{"id": "a", "text": "effectively increases the area of the control surface.", "correct": false}, {"id": "b", "text": "assists the pilot to move the controls.", "correct": true}, {"id": "c", "text": "is used to trim the appropriate axis of the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Elevons combine the functions of both', '[{"id": "a", "text": "rudder and elevator.", "correct": false}, {"id": "b", "text": "elevator and aileron.", "correct": true}, {"id": "c", "text": "rudder and aileron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Flutter can be reduced by using', '[{"id": "a", "text": "a horn balance.", "correct": false}, {"id": "b", "text": "mass balancing.", "correct": true}, {"id": "c", "text": "servo tabs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An elevator provides control about the', '[{"id": "a", "text": "longitudinal axis.", "correct": false}, {"id": "b", "text": "lateral axis.", "correct": true}, {"id": "c", "text": "horizontal stabilizer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The outboard ailerons on some large aircraft', '[{"id": "a", "text": "are isolated at high speeds.", "correct": true}, {"id": "b", "text": "are isolated to improve sensitivity.", "correct": false}, {"id": "c", "text": "are isolated at low speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which wing increases drag when the ailerons are moved?', '[{"id": "a", "text": "Both wings increase drag but the wing with the down-going aileron increases more.", "correct": true}, {"id": "b", "text": "Both wings have an equal increase in drag.", "correct": false}, {"id": "c", "text": "Both wings increase drag but the wing with the up-going aileron increases more.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which flap will increase wing area and camber?', '[{"id": "a", "text": "Slot.", "correct": false}, {"id": "b", "text": "Split.", "correct": false}, {"id": "c", "text": "Fowler.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Wing loading of an aircraft', '[{"id": "a", "text": "varies with dynamic loading due to air currents.", "correct": true}, {"id": "b", "text": "is independent of altitude.", "correct": false}, {"id": "c", "text": "decreases with density.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An automatic slat will lift by itself when the angle of attack is', '[{"id": "a", "text": "high.", "correct": true}, {"id": "b", "text": "high or low.", "correct": false}, {"id": "c", "text": "low.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On aircraft fitted with spoilers for lateral control, roll to the right is caused by', '[{"id": "a", "text": "left spoilers extending, right spoilers remaining retracted.", "correct": false}, {"id": "b", "text": "right spoilers extending, left spoilers remaining retracted.", "correct": true}, {"id": "c", "text": "left and right spoilers extending.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A split flap increases lift by increasing', '[{"id": "a", "text": "the angle of attachment of the lower hinged portion.", "correct": true}, {"id": "b", "text": "the surface area.", "correct": false}, {"id": "c", "text": "the camber of the top surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When the trailing edge flaps are lowered, the aircraft will', '[{"id": "a", "text": "pitch nose up.", "correct": false}, {"id": "b", "text": "pitch nose down.", "correct": true}, {"id": "c", "text": "sink.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In aileron control', '[{"id": "a", "text": "the up going aileron moves further than down going aileron.", "correct": true}, {"id": "b", "text": "the down going aileron moves further than up going aileron.", "correct": false}, {"id": "c", "text": "it is assisted by the rudder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The aircraft is controlled about the lateral axis by the', '[{"id": "a", "text": "ailerons.", "correct": false}, {"id": "b", "text": "elevator.", "correct": true}, {"id": "c", "text": "rudder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The aircraft is controlled about the normal axis by the', '[{"id": "a", "text": "ailerons.", "correct": false}, {"id": "b", "text": "elevator.", "correct": false}, {"id": "c", "text": "rudder.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Dutch roll is', '[{"id": "a", "text": "a combined yawing and rolling motion.", "correct": true}, {"id": "b", "text": "primarily a pitching instability.", "correct": false}, {"id": "c", "text": "a type of slow roll.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The aircraft is controlled about the longitudinal axis by the', '[{"id": "a", "text": "ailerons.", "correct": true}, {"id": "b", "text": "elevator.", "correct": false}, {"id": "c", "text": "rudder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Ruddervators when moved, will move', '[{"id": "a", "text": "opposite to each other only.", "correct": false}, {"id": "b", "text": "together only.", "correct": false}, {"id": "c", "text": "either opposite each other or together, depending on the selection.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As a consequence of the C of G being close to its aft limit', '[{"id": "a", "text": "the stick forces will be high in fore and aft pitch, due to the high longitudinal stability.", "correct": false}, {"id": "b", "text": "the stick forces to manoeuvre longitudinally will be low due to the low stability.", "correct": true}, {"id": "c", "text": "the stick forces when pitching the nose down will be very high.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is the term used for the amount of water in the atmosphere?', '[{"id": "a", "text": "Relative humidity.", "correct": false}, {"id": "b", "text": "Absolute humidity.", "correct": true}, {"id": "c", "text": "Dew point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An anti-balance tab is moved', '[{"id": "a", "text": "via a fixed linkage.", "correct": true}, {"id": "b", "text": "hydraulically.", "correct": false}, {"id": "c", "text": "when the C.G. changes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A servo tab is operated', '[{"id": "a", "text": "automatically, and moves in the same direction as the main control surfaces.", "correct": false}, {"id": "b", "text": "directly by the pilot to produce forces which in turn move the main control surfaces.", "correct": true}, {"id": "c", "text": "by a trim wheel and moves in the opposite direction to the main control sufraces when moved.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On an aircraft with an all-moving tailplane, pitch up is caused by', '[{"id": "a", "text": "decreasing tailplane incidence.", "correct": true}, {"id": "b", "text": "up movement of the elevator trim tab.", "correct": false}, {"id": "c", "text": "increasing tailplane incidence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When checking full range of control surface movement, they must be positioned by', '[{"id": "a", "text": "moving them by hand directly until against the primary stops.", "correct": false}, {"id": "b", "text": "moving them by hand directly until against the secondary stops.", "correct": false}, {"id": "c", "text": "operating the control cabin controls until the system is against the primary stops.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An excess of aerodynamic balance would move the control surface centre of pressure', '[{"id": "a", "text": "rearwards, resulting in too much assistance.", "correct": false}, {"id": "b", "text": "rearwards, resulting in loss of assistance.", "correct": false}, {"id": "c", "text": "forwards, resulting in an unstable overbalance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A flying control mass balance weight', '[{"id": "a", "text": "keeps the control surface C of G as close to the trailing edge as possible.", "correct": false}, {"id": "b", "text": "tends to move the control surface C of G close to the hinge line.", "correct": true}, {"id": "c", "text": "ensures that the C of G always acts to aid the pilot thus relieving control column load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The type of flap which extends rearwards when lowered is called a', '[{"id": "a", "text": "plain flap.", "correct": false}, {"id": "b", "text": "split flap.", "correct": false}, {"id": "c", "text": "Fowler flap.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following trailing edge flaps give an increase in wing area?', '[{"id": "a", "text": "Split flap.", "correct": false}, {"id": "b", "text": "Fowler flap.", "correct": true}, {"id": "c", "text": "Slotted flap.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following is not a primary flying control?', '[{"id": "a", "text": "Elevator.", "correct": false}, {"id": "b", "text": "Tailplane.", "correct": true}, {"id": "c", "text": "Rudder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A leading edge slat is a device for', '[{"id": "a", "text": "increasing the stalling angle of the wing.", "correct": true}, {"id": "b", "text": "decreasing the stalling angle of the wing.", "correct": false}, {"id": "c", "text": "decreasing wing drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A Krueger flap is', '[{"id": "a", "text": "a flap which extends rearwards but does not lower.", "correct": false}, {"id": "b", "text": "a leading edge flap which hinges forward.", "correct": true}, {"id": "c", "text": "a leading edge slat which extends forward.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A tab which assists the pilot to move a flying control by moving automatically in the opposite direction to the control surface is called a', '[{"id": "a", "text": "servo tab.", "correct": false}, {"id": "b", "text": "geared balance tab.", "correct": true}, {"id": "c", "text": "trim tab.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is attached to the rear of the vertical stabilizer?', '[{"id": "a", "text": "Elevator.", "correct": false}, {"id": "b", "text": "Aileron.", "correct": false}, {"id": "c", "text": "Rudder.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is fitted on the aircraft to enable the pilot to reduce his speed rapidly in event of severe turbulence, or speed tending to rise above the Never Exceed Limit?', '[{"id": "a", "text": "Lift dumpers.", "correct": false}, {"id": "b", "text": "Air brakes.", "correct": true}, {"id": "c", "text": "Wheel brakes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When spoilers are used asymmetrically, they combine with', '[{"id": "a", "text": "ailerons.", "correct": true}, {"id": "b", "text": "rudder.", "correct": false}, {"id": "c", "text": "elevators.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is used to correct any tendency of the aircraft to move towards an undesirable flight attitude?', '[{"id": "a", "text": "Trim tabs.", "correct": true}, {"id": "b", "text": "Spring tabs.", "correct": false}, {"id": "c", "text": "Balance tabs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The layer of air over the surface of an aerofoil which is slower moving, in relation to the rest of the airflow, is known as', '[{"id": "a", "text": "none of the above are correct.", "correct": false}, {"id": "b", "text": "camber layer.", "correct": false}, {"id": "c", "text": "boundary layer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A control surface which forms a slot when deployed is called a', '[{"id": "a", "text": "slat.", "correct": true}, {"id": "b", "text": "slot.", "correct": false}, {"id": "c", "text": "flap.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Asymmetric flaps will cause', '[{"id": "a", "text": "the aircraft to descend.", "correct": false}, {"id": "b", "text": "the aircraft to ascend.", "correct": false}, {"id": "c", "text": "one wing to rise.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When airflow velocity over an upper cambered surface of an aerofoil decreases, what takes place?', '[{"id": "a", "text": "Pressure decreases, lift increases.", "correct": false}, {"id": "b", "text": "Pressure increases, lift decreases.", "correct": true}, {"id": "c", "text": "Pressure increases, lift increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is a controlling factor of turbulence and skin friction?', '[{"id": "a", "text": "Countersunk rivets used on skin exterior.", "correct": false}, {"id": "b", "text": "Aspect ratio.", "correct": false}, {"id": "c", "text": "Fineness ratio.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Changes in aircraft weight', '[{"id": "a", "text": "cause corresponding changes in total drag due to the associated lift change.", "correct": true}, {"id": "b", "text": "will not affect total drag since it is dependant only upon speed.", "correct": false}, {"id": "c", "text": "will only affect total drag if the lift is kept constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When an aircraft stalls', '[{"id": "a", "text": "lift increases and drag decreases.", "correct": false}, {"id": "b", "text": "lift and drag increase.", "correct": false}, {"id": "c", "text": "lift decreases and drag increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Spoiler panels are positioned so that when deployed', '[{"id": "a", "text": "roll will not occur.", "correct": false}, {"id": "b", "text": "pitch trim is not affected.", "correct": true}, {"id": "c", "text": "no yaw takes place.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The aircraft stalling speed will', '[{"id": "a", "text": "only change if the MTWA were changed.", "correct": false}, {"id": "b", "text": "be unaffected by aircraft weight changes since it is dependant upon the angle of attack.", "correct": false}, {"id": "c", "text": "increase with an increase in weight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In a bank and turn', '[{"id": "a", "text": "extra lift is not required if thrust is increased.", "correct": false}, {"id": "b", "text": "extra lift is not required.", "correct": false}, {"id": "c", "text": "extra lift is required.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The method employed to mass balance control surfaces is to', '[{"id": "a", "text": "fit bias strips to the trailing edge of the surfaces.", "correct": false}, {"id": "b", "text": "attach weights forward of the hinge line.", "correct": true}, {"id": "c", "text": "allow the leading edge of the surface to project into the airflow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Control surface flutter may be caused by', '[{"id": "a", "text": "excessive play in trim tab attachments.", "correct": true}, {"id": "b", "text": "high static friction in trim tab control tabs.", "correct": false}, {"id": "c", "text": "incorrect angular movement of trim tabs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A differential aileron control system results in', '[{"id": "a", "text": "aileron drag being reduced on the inner wing in a turn.", "correct": false}, {"id": "b", "text": "aileron drag being reduced on the outer wing in a turn.", "correct": true}, {"id": "c", "text": "aileron drag being compensated by small rudder movements.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The primary function of a flap is', '[{"id": "a", "text": "to trim the aircraft longitudinally.", "correct": false}, {"id": "b", "text": "to alter the position of the centre of gravity.", "correct": false}, {"id": "c", "text": "to alter the lift of an aerofoil.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The angle of attack at which stall occurs', '[{"id": "a", "text": "can be varied by using flaps and slats.", "correct": false}, {"id": "b", "text": "depends on the weight of the aircraft.", "correct": false}, {"id": "c", "text": "cannot be varied, it is always constant.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The stalling speed of an aircraft', '[{"id": "a", "text": "is increased when it is heavier.", "correct": true}, {"id": "b", "text": "does not change.", "correct": false}, {"id": "c", "text": "is increased when it is lighter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A wing flap which has dropped or partially extended on one wing in flight will lead to', '[{"id": "a", "text": "a fixed banked attitude which would be corrected by use of the rudder.", "correct": false}, {"id": "b", "text": "a pitching moment which would be corrected by used of the elevators.", "correct": false}, {"id": "c", "text": "a steady rolling tendency which would be corrected by use of the ailerons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With an increase in the amount of flap deployment, the stalling angle of a wing', '[{"id": "a", "text": "remains the same.", "correct": false}, {"id": "b", "text": "increases.", "correct": false}, {"id": "c", "text": "decreases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Aerodynamic balance of a control surface may be achieved', '[{"id": "a", "text": "by a horn at the extremity of the surface forward of the hinge line.", "correct": true}, {"id": "b", "text": "by weights added to the control surface aft of the hinge line.", "correct": false}, {"id": "c", "text": "by a trimming strip at the trailing edge of the surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A control surface is provided with aerodynamic balancing to', '[{"id": "a", "text": "assist the pilot in moving the control.", "correct": true}, {"id": "b", "text": "increase stability.", "correct": false}, {"id": "c", "text": "decrease the drag when the control is deflected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Downward displacement of an aileron', '[{"id": "a", "text": "increases the angle at which its wing stalls.", "correct": false}, {"id": "b", "text": "decreases the angle at which its wing will stall.", "correct": true}, {"id": "c", "text": "has no effect on its wing stalling angle, it only affects the stalling speed on that wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Due to the tailplane angle of attack change, the flap-induced downwash on the tailplane', '[{"id": "a", "text": "will tend to cause an aircraft nose-up pitch.", "correct": true}, {"id": "b", "text": "may cause a nose-down or nose-up pitch depending upon the initial tailplane load.", "correct": false}, {"id": "c", "text": "will tend to cause an aircraft nose down pitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Due to the change in lift coefficient accompanying extension of the flaps, to maintain the lift constant it would be necessary to', '[{"id": "a", "text": "raise the nose.", "correct": false}, {"id": "b", "text": "lower the nose.", "correct": true}, {"id": "c", "text": "keep the pitch attitude constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A differential aileron control is one which gives', '[{"id": "a", "text": "the down-going aileron more travel than the up-going one.", "correct": false}, {"id": "b", "text": "equal aileron travel in each direction, but variable for stick movement.", "correct": false}, {"id": "c", "text": "a larger aileron up travel than down.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which leading edge device improves the laminar flow over the wing?', '[{"id": "a", "text": "Flap and slat.", "correct": false}, {"id": "b", "text": "Slat.", "correct": true}, {"id": "c", "text": "Flap.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The balance tab is an auxiliary surface fitted to a main control surface', '[{"id": "a", "text": "operating automatically to assist the pilot in moving the controls.", "correct": true}, {"id": "b", "text": "operated independently at which point in the length of cable the tensiometer is applied.", "correct": false}, {"id": "c", "text": "operating automatically to provide feel to the controls.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Aerodynamic balancing of flight controls is achieved by', '[{"id": "a", "text": "placing a weight ahead of the hinge point.", "correct": false}, {"id": "b", "text": "placing a weight in the leading edge of the control surface.", "correct": false}, {"id": "c", "text": "providing a portion of the control surface ahead of the hinge point.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Aerodynamic balance is used to', '[{"id": "a", "text": "reduce the control load to zero.", "correct": false}, {"id": "b", "text": "make the flying controls easier to move.", "correct": true}, {"id": "c", "text": "prevent flutter of the flying controls.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A horn balance is', '[{"id": "a", "text": "a rod projecting forward from the control surface with a weight on the end.", "correct": false}, {"id": "b", "text": "a rod projecting upward from the main control surface to which the control cables are attached.", "correct": false}, {"id": "c", "text": "a projection of the outer edge of the control surface forward of the hinge line.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A control surface is mass balanced by', '[{"id": "a", "text": "the attachment of weights acting on the hinge line.", "correct": false}, {"id": "b", "text": "fitting a balance tab.", "correct": false}, {"id": "c", "text": "the attachment of weights acting forward of the hinge line.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The purpose of anti-balance tabs is to', '[{"id": "a", "text": "relieve stick loads.", "correct": false}, {"id": "b", "text": "trim the aircraft.", "correct": false}, {"id": "c", "text": "give more feel to the control column.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'You have adjusted the elevator trim tab to correct for nose heavy. What was the direction of travel of the trim tab?', '[{"id": "a", "text": "The elevator trim tab has moved down.", "correct": true}, {"id": "b", "text": "The elevator trim tab has moved up.", "correct": false}, {"id": "c", "text": "The port elevator tab has moved up and starboard moved down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The tropopause exists at about', '[{"id": "a", "text": "18,000 ft.", "correct": false}, {"id": "b", "text": "30,000 ft.", "correct": false}, {"id": "c", "text": "36,000 ft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Induced drag curve characteristics of a slender delta wing are such that there is', '[{"id": "a", "text": "an increase in gradient with wing speed.", "correct": false}, {"id": "b", "text": "no change in gradient with wing speed.", "correct": false}, {"id": "c", "text": "decrease in gradient with wing speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft is yawing left, the trim tab on the rudder would be positioned', '[{"id": "a", "text": "to the right, moving the rudder left.", "correct": false}, {"id": "b", "text": "to the centre.", "correct": false}, {"id": "c", "text": "to the left, moving the rudder right.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Instability giving roll and yaw', '[{"id": "a", "text": "is dutch roll.", "correct": true}, {"id": "b", "text": "is longitudinal stability.", "correct": false}, {"id": "c", "text": "is lateral stability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Vortex generators are fitted to', '[{"id": "a", "text": "move transition point rearwards.", "correct": false}, {"id": "b", "text": "move transition point forwards.", "correct": true}, {"id": "c", "text": "advance the onset of flow separation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Leading edge flaps', '[{"id": "a", "text": "increase stalling angle of the wing.", "correct": true}, {"id": "b", "text": "decrease stalling angle of the wing.", "correct": false}, {"id": "c", "text": "do not change the stalling angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Krueger flaps are on', '[{"id": "a", "text": "the leading edge.", "correct": true}, {"id": "b", "text": "either the leading or training edge.", "correct": false}, {"id": "c", "text": "the trailing edge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Sweepback will', '[{"id": "a", "text": "decrease lateral stability.", "correct": false}, {"id": "b", "text": "not affect lateral stability.", "correct": false}, {"id": "c", "text": "increase lateral stability.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A plain flap', '[{"id": "a", "text": "does not increase the wing area on deployment.", "correct": true}, {"id": "b", "text": "is attached to the leading edge of the wing.", "correct": false}, {"id": "c", "text": "forms part of lower trailing edge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A split flap, when deployed', '[{"id": "a", "text": "is used only on high speed aircraft.", "correct": false}, {"id": "b", "text": "increases lift without a corresponding increase in drag.", "correct": false}, {"id": "c", "text": "increases drag with little lift coefficient increase, from intermediate to fully down.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A flying control mass balance weight', '[{"id": "a", "text": "keeps the control surface C of G as close to the trailing edge as possible.", "correct": false}, {"id": "b", "text": "tends to move the control surface C of G close to the hinge line.", "correct": true}, {"id": "c", "text": "tends to move the control surface C of G forward of the hinge line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An elevator controls the aircraft motion in', '[{"id": "a", "text": "yaw.", "correct": false}, {"id": "b", "text": "roll.", "correct": false}, {"id": "c", "text": "pitch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Air above Mach 0.7 is', '[{"id": "a", "text": "compressible only when above the speed of sound.", "correct": false}, {"id": "b", "text": "incompressible.", "correct": false}, {"id": "c", "text": "compressible.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Supersonic air passing through a divergent duct causes the', '[{"id": "a", "text": "pressure to increase, velocity to increase.", "correct": false}, {"id": "b", "text": "pressure to increase, velocity to decrease.", "correct": false}, {"id": "c", "text": "pressure to decrease, velocity to increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A nose down change of trim (tuck-under) occurs due to shock induced', '[{"id": "a", "text": "tip stall on a delta wing aircraft.", "correct": true}, {"id": "b", "text": "root stall on a delta wing aircraft.", "correct": false}, {"id": "c", "text": "tip stall on a straight wing aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A symmetrical aerofoil is accelerating through Mach 1 with an angle of attack of 0°. A shock wave will form', '[{"id": "a", "text": "on the upper and lower surface and will move aft until the point of maximum camber.", "correct": false}, {"id": "b", "text": "on the upper and lower surface and will move aft.", "correct": true}, {"id": "c", "text": "on the upper surface only and move aft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Shock stall', '[{"id": "a", "text": "occurs at high speeds.", "correct": true}, {"id": "b", "text": "is a flap down stall and occurs at high speeds.", "correct": false}, {"id": "c", "text": "occurs at low speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As you approach supersonic speed', '[{"id": "a", "text": "thrust is reduced.", "correct": false}, {"id": "b", "text": "total drag is increased.", "correct": true}, {"id": "c", "text": "lift is reduced.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Mach trim in some aircraft assists', '[{"id": "a", "text": "lateral stability.", "correct": false}, {"id": "b", "text": "vertical stability.", "correct": false}, {"id": "c", "text": "longitudinal stability.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Before an aircraft reaches critical mach', '[{"id": "a", "text": "the nose pitches up because the CP moves Forward.", "correct": true}, {"id": "b", "text": "the aircraft buffets because the CP moves to the shock wave.", "correct": false}, {"id": "c", "text": "the nose pitches down because the CP moves rear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a standard day, at which altitude will the speed of sound be the greatest?', '[{"id": "a", "text": "20,000 ft.", "correct": false}, {"id": "b", "text": "10,000 ft.", "correct": false}, {"id": "c", "text": "Sea level.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following will increase the Critical Mach Number of an aerofoil?', '[{"id": "a", "text": "Using a thin airfoil and sweeping the wings back.", "correct": true}, {"id": "b", "text": "Decreasing the fineness ratio of the wings.", "correct": false}, {"id": "c", "text": "Increasing the aspect ratio of the wings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As an aircraft accelerates through the transonic region, the centre of pressure tends to', '[{"id": "a", "text": "turn into a shock wave.", "correct": false}, {"id": "b", "text": "move rearward.", "correct": true}, {"id": "c", "text": "move forward.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Supersonic air going through an incipient shock wave will decrease its speed and', '[{"id": "a", "text": "decrease temperature and increase density.", "correct": false}, {"id": "b", "text": "increase temperature and decrease density.", "correct": false}, {"id": "c", "text": "increase temperature and increase density.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An increase in mach number will cause the', '[{"id": "a", "text": "CofP to move rearwards giving more downwash on the tail plane.", "correct": false}, {"id": "b", "text": "CofP to move forwards giving less downwash on the tail plane.", "correct": false}, {"id": "c", "text": "CofP to move rearwards giving less downwash on the tail plane.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At speeds above Mach 1, shockwaves will form above and below the wing', '[{"id": "a", "text": "at the trailing edge.", "correct": false}, {"id": "b", "text": "at both the leading edge and the trailing edge.", "correct": true}, {"id": "c", "text": "at the leading edge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Above the critical mach number, the drag coefficient', '[{"id": "a", "text": "increases.", "correct": true}, {"id": "b", "text": "remains the same.", "correct": false}, {"id": "c", "text": "decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Mach trim counters', '[{"id": "a", "text": "longitudinal instability.", "correct": true}, {"id": "b", "text": "vertical instability.", "correct": false}, {"id": "c", "text": "lateral instability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At high Mach Numbers above Mach 2.2, some aircraft metals', '[{"id": "a", "text": "such as aluminium, become brittle.", "correct": false}, {"id": "b", "text": "lose their strength due to the kinetic heating effect.", "correct": true}, {"id": "c", "text": "will shrink due to the extreme pressures involved.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Mach trim operates', '[{"id": "a", "text": "along the longitudinal axis.", "correct": true}, {"id": "b", "text": "along the lateral axis.", "correct": false}, {"id": "c", "text": "to reduce Dutch roll.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'To increase critical mach number', '[{"id": "a", "text": "the wings are swept.", "correct": true}, {"id": "b", "text": "elevons are fitted.", "correct": false}, {"id": "c", "text": "tailerons are fitted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When approaching the speed of sound the', '[{"id": "a", "text": "pressure above the wing exceeds the pressure below the wing in places.", "correct": true}, {"id": "b", "text": "pressure above the wing can never exceed the pressure below the wing.", "correct": false}, {"id": "c", "text": "pressure above the wing equals the pressure below the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Airspeeds above the speed of sound, but not exceeding 4 times the speed of sound are', '[{"id": "a", "text": "supersonic.", "correct": true}, {"id": "b", "text": "hypersonic.", "correct": false}, {"id": "c", "text": "hyposonic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft experiences a large loss of lift and a big increase in drag in straight and level flight, what would be the most probable cause?', '[{"id": "a", "text": "Atmospheric conditions.", "correct": false}, {"id": "b", "text": "Aircraft reached its critical mach number.", "correct": true}, {"id": "c", "text": "Severe head winds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A Mach Trimmer is a device which', '[{"id": "a", "text": "prevents the aircraft from exceeding its critical Mach No.", "correct": false}, {"id": "b", "text": "automatically compensates for trim changes in the transonic region.", "correct": true}, {"id": "c", "text": "switches out trim control to prevent damage in the transonic speed range.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Mach trimming is initiated by an input signal from the', '[{"id": "a", "text": "IRS.", "correct": false}, {"id": "b", "text": "vertical gyro.", "correct": false}, {"id": "c", "text": "CADC.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Mach trim prevents', '[{"id": "a", "text": "the nose dropping in a low speed turn.", "correct": false}, {"id": "b", "text": "the nose dropping at high speed.", "correct": true}, {"id": "c", "text": "the nose lifting at high speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Critical Mach No. may be increased by', '[{"id": "a", "text": "using a higher thickness/chord ratio wing.", "correct": false}, {"id": "b", "text": "sweeping back the wing.", "correct": true}, {"id": "c", "text": "using more powerful engines.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Airflow either side of a normal shock wave is', '[{"id": "a", "text": "sonic upstream and downstream.", "correct": false}, {"id": "b", "text": "sonic upstream, subsonic downstream.", "correct": true}, {"id": "c", "text": "subsonic upstream, sonic downstream.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Mach Number is defined as', '[{"id": "a", "text": "speed of sound at sea level divided by local speed of sound.", "correct": false}, {"id": "b", "text": "IAS divided by the local speed of sound.", "correct": false}, {"id": "c", "text": "TAS divided by local speed of sound.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The reason for sharp leading edged wings on high speed aircraft is to', '[{"id": "a", "text": "enable the shockwave to be accurately positioned.", "correct": false}, {"id": "b", "text": "decrease wave drag.", "correct": true}, {"id": "c", "text": "decrease boundary layer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Critical Mach Number is defined as', '[{"id": "a", "text": "that number at which the airflow becomes supersonic.", "correct": false}, {"id": "b", "text": "that free-stream Mach Number at which some part of the airflow over the aircraft becomes sonic.", "correct": true}, {"id": "c", "text": "the minimum mach number at which the aircraft can go supersonic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The transonic region is a region of', '[{"id": "a", "text": "all subsonic.", "correct": false}, {"id": "b", "text": "all supersonic.", "correct": false}, {"id": "c", "text": "mixed airflow.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Immediately downstream of an oblique shockwave is always', '[{"id": "a", "text": "supersonic.", "correct": true}, {"id": "b", "text": "the same as upstream.", "correct": false}, {"id": "c", "text": "subsonic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Wave drag', '[{"id": "a", "text": "increases in the supersonic region.", "correct": false}, {"id": "b", "text": "increases at the low speed stall.", "correct": false}, {"id": "c", "text": "increases in the transonic region.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'For increased Mcrit', '[{"id": "a", "text": "decrease thickness/chord ratio.", "correct": true}, {"id": "b", "text": "decrease sweepback.", "correct": false}, {"id": "c", "text": "decrease true airspeed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Symptoms of shock stall are', '[{"id": "a", "text": "decrease in speed, buffet and movement of the centre of pressure.", "correct": false}, {"id": "b", "text": "buffet, loss of control, and instability.", "correct": true}, {"id": "c", "text": "compressibility effects, buffet and loss of control.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Sweepback increases Mcrit by', '[{"id": "a", "text": "decreasing the amount of airflow over the lowest point on the aerofoil section.", "correct": false}, {"id": "b", "text": "decreasing the amount of airflow over the highest point on the aerofoil section.", "correct": true}, {"id": "c", "text": "increasing the amount of airflow over the highest point on the aerofoil section.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Mach number is', '[{"id": "a", "text": "the ratio of the aircrafts TAS to the speed of sound at the same atmospheric conditions.", "correct": true}, {"id": "b", "text": "the ratio of the aircrafts IAS to the speed of sound at the same atmospheric conditions.", "correct": false}, {"id": "c", "text": "the ratio of the aircrafts TAS to the speed of sound at sea level.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The critical Mach number is', '[{"id": "a", "text": "the Mach No. when a shock wave forms at the leading edge.", "correct": false}, {"id": "b", "text": "the Mach No. when the aircraft reaches the speed of sound.", "correct": false}, {"id": "c", "text": "the aircraft Mach No. when the airflow reaches the speed of sound at some point on the aircraft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Above the Critical Mach No. the drag coefficient will', '[{"id": "a", "text": "remain the same.", "correct": false}, {"id": "b", "text": "start to increase.", "correct": true}, {"id": "c", "text": "start to decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A wing of low thickness/chord ratio, the Critical Mach No. will be', '[{"id": "a", "text": "lower than a wing of high thickness/chord ratio.", "correct": false}, {"id": "b", "text": "higher than a wing of high thickness/chord ratio.", "correct": true}, {"id": "c", "text": "the same as a wing of high thickness/chord ratio.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aeroplane flying above the Critical Mach No. will usually experience', '[{"id": "a", "text": "a nose up pitch.", "correct": false}, {"id": "b", "text": "an oscillation in pitch.", "correct": false}, {"id": "c", "text": "a nose down pitch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Tuck-under can be counteracted by', '[{"id": "a", "text": "mach trim.", "correct": true}, {"id": "b", "text": "aileron reversal.", "correct": false}, {"id": "c", "text": "trim tabs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What causes tuckunder?', '[{"id": "a", "text": "Flap back effect.", "correct": false}, {"id": "b", "text": "Shock stall.", "correct": true}, {"id": "c", "text": "Aileron reversal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When does a shock stall occur?', '[{"id": "a", "text": "When the aircraft forward speed is above Mach One.", "correct": false}, {"id": "b", "text": "At the critical Mach number of the aeroplane.", "correct": true}, {"id": "c", "text": "When the aircraft reaches speed of sound in a dive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With an increase in altitude under I.S.A. conditions, the temperature in the troposphere', '[{"id": "a", "text": "increases.", "correct": false}, {"id": "b", "text": "remains constant.", "correct": false}, {"id": "c", "text": "decreases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Air either side of an oblique shockwave is generally', '[{"id": "a", "text": "sonic.", "correct": false}, {"id": "b", "text": "supersonic.", "correct": true}, {"id": "c", "text": "subsonic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Downstream of a normal shock wave', '[{"id": "a", "text": "pressure decreases temperature increases.", "correct": false}, {"id": "b", "text": "pressure and temperature increase.", "correct": true}, {"id": "c", "text": "pressure and temperature decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Speed of sound varies with', '[{"id": "a", "text": "altitude.", "correct": false}, {"id": "b", "text": "temperature.", "correct": true}, {"id": "c", "text": "pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Immediately downstream of a normal shockwave, air is always', '[{"id": "a", "text": "subsonic.", "correct": true}, {"id": "b", "text": "supersonic.", "correct": false}, {"id": "c", "text": "the same as upstream.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Increased sweepback', '[{"id": "a", "text": "improves tip stall characteristics.", "correct": false}, {"id": "b", "text": "raises Mcrit.", "correct": true}, {"id": "c", "text": "decreases stability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Aerodynamic heating', '[{"id": "a", "text": "increases as a function of airspeed.", "correct": true}, {"id": "b", "text": "increases with skin friction.", "correct": false}, {"id": "c", "text": "decreases with altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'To overcome ineffective control surface problems in the transonic region', '[{"id": "a", "text": "an all moving tailplane may be used.", "correct": true}, {"id": "b", "text": "hydraulic powered elevators may be used.", "correct": false}, {"id": "c", "text": "Frise ailerons may be used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft flying below the tropopause descends at a constant True Airspeed, its Mach. No.', '[{"id": "a", "text": "will remain the same.", "correct": false}, {"id": "b", "text": "increase.", "correct": false}, {"id": "c", "text": "decrease.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'To counter the effect of a shift of centre of pressure as an aircraft flies through the transonic region, fuel is pumped', '[{"id": "a", "text": "forwards.", "correct": false}, {"id": "b", "text": "backwards.", "correct": true}, {"id": "c", "text": "sideways.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft flying above the tropopause descends at a constant True Airspeed, its Mach No. will', '[{"id": "a", "text": "remain the same.", "correct": true}, {"id": "b", "text": "decrease.", "correct": false}, {"id": "c", "text": "increase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The velocity of sound with an increase in altitude will', '[{"id": "a", "text": "remain constant.", "correct": false}, {"id": "b", "text": "increase.", "correct": false}, {"id": "c", "text": "decrease.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Mach number equals the ratio of', '[{"id": "a", "text": "altitude to airspeed.", "correct": false}, {"id": "b", "text": "sonic speed to indicated airspeed.", "correct": false}, {"id": "c", "text": "true airspeed to local sonic speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Tuck-under is caused by', '[{"id": "a", "text": "tip stall on a straight wing aircraft.", "correct": false}, {"id": "b", "text": "tip stall on a swept wing aircraft.", "correct": true}, {"id": "c", "text": "root stall on a swept wing aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The purpose of sweepback on an aerofoil is to', '[{"id": "a", "text": "decrease drag.", "correct": false}, {"id": "b", "text": "decrease Mcrit.", "correct": false}, {"id": "c", "text": "increase Mcrit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the airspeed over a cambered wing is increased, a shock wave will appear initially', '[{"id": "a", "text": "at the leading edge.", "correct": false}, {"id": "b", "text": "at the trailing edge.", "correct": false}, {"id": "c", "text": "near the point of maximum curvature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Drooping of helicopter blades is compensated by', '[{"id": "a", "text": "flapping.", "correct": false}, {"id": "b", "text": "dragging.", "correct": false}, {"id": "c", "text": "centrifugal force.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With a drop in ambient temperature, an aircraft service ceiling will', '[{"id": "a", "text": "lower.", "correct": false}, {"id": "b", "text": "rise.", "correct": true}, {"id": "c", "text": "not be affected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Climbs with forward speed require less power than vertical climbs, because of', '[{"id": "a", "text": "translational lift.", "correct": true}, {"id": "b", "text": "increased inertia.", "correct": false}, {"id": "c", "text": "forward momentum.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Tracking is carried out to_____________the main rotor blade tip path.', '[{"id": "a", "text": "restore.", "correct": false}, {"id": "b", "text": "align.", "correct": true}, {"id": "c", "text": "balance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What principle does the delta 3 hinge use?', '[{"id": "a", "text": "Triangular pitch change lever.", "correct": true}, {"id": "b", "text": "Flapping actuators.", "correct": false}, {"id": "c", "text": "Offset hinges.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The bell stability augmentation system is based on', '[{"id": "a", "text": "flapping hinges.", "correct": false}, {"id": "b", "text": "offset hinges.", "correct": false}, {"id": "c", "text": "gyroscopic forces.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The difference between transient droop and static droop is', '[{"id": "a", "text": "overswing.", "correct": true}, {"id": "b", "text": "underswing.", "correct": false}, {"id": "c", "text": "a hole in one.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An helicopter fin helps to give', '[{"id": "a", "text": "longitudinal stability about the normal axis.", "correct": false}, {"id": "b", "text": "directional stability about the normal axis.", "correct": true}, {"id": "c", "text": "directional stability about the longitudinal axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Solidity of the rotor is the ratio of the', '[{"id": "a", "text": "blade area to disc area.", "correct": true}, {"id": "b", "text": "all up weight to blade area.", "correct": false}, {"id": "c", "text": "all up weight to disc area.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lift in a helicopter is a result of', '[{"id": "a", "text": "pitch * square root of speed.", "correct": false}, {"id": "b", "text": "angle of attack * velocity squared.", "correct": true}, {"id": "c", "text": "angle of attack * velocity squared and forward speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The layer of air over the surface of an aerofoil which is slower moving, in relation to the rest of the airflow, is known as', '[{"id": "a", "text": "camber layer.", "correct": false}, {"id": "b", "text": "boundary layer.", "correct": true}, {"id": "c", "text": "none of the above are correct.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When airflow velocity over an upper cambered surface of an aerofoil decreases, what takes place?', '[{"id": "a", "text": "Pressure increases, lift decreases.", "correct": true}, {"id": "b", "text": "Pressure decreases, lift increases.", "correct": false}, {"id": "c", "text": "Pressure increases, lift increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is a controlling factor of turbulence and skin friction?', '[{"id": "a", "text": "Countersunk rivets used on skin exterior.", "correct": false}, {"id": "b", "text": "Fineness ratio.", "correct": true}, {"id": "c", "text": "Aspect ratio.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Changes in aircraft weight', '[{"id": "a", "text": "will only affect total drag if the lift is kept constant.", "correct": false}, {"id": "b", "text": "will not affect total drag since it is dependant only upon speed.", "correct": false}, {"id": "c", "text": "cause corresponding changes in total drag due to the associated lift change.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When an aerofoil stalls', '[{"id": "a", "text": "lift and drag increase.", "correct": false}, {"id": "b", "text": "lift decreases and drag increases.", "correct": true}, {"id": "c", "text": "lift increases and drag decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Translational drift is', '[{"id": "a", "text": "the tendency for the aircraft to drift laterally.", "correct": true}, {"id": "b", "text": "the tendency for the aircraft to turn to port.", "correct": false}, {"id": "c", "text": "the tendency for the aircraft to pitch nose up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The tropopause exists at about', '[{"id": "a", "text": "18,000 ft.", "correct": false}, {"id": "b", "text": "30,000 ft.", "correct": false}, {"id": "c", "text": "36,000 ft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The centre of pressure of an aerofoil is that point on the cord line', '[{"id": "a", "text": "which moves most, with changes in angle of attack, if the section is symmetrical.", "correct": false}, {"id": "b", "text": "at which the highest pressure is said to act.", "correct": false}, {"id": "c", "text": "at which the lift forces resultant is said to act.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Dihedral wings combat instability in', '[{"id": "a", "text": "yaw.", "correct": false}, {"id": "b", "text": "side-slip.", "correct": true}, {"id": "c", "text": "pitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft, which is longitudinally stable, will tend to return to level flight after a movement in which axis?', '[{"id": "a", "text": "Pitch.", "correct": true}, {"id": "b", "text": "Yaw.", "correct": false}, {"id": "c", "text": "Roll.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The normal axis of an aircraft passes through', '[{"id": "a", "text": "the centre of gravity.", "correct": true}, {"id": "b", "text": "a point at the centre of the wings.", "correct": false}, {"id": "c", "text": "at the centre of pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Due to the change in downwash on an untapered wing (i.e. one of constant chord length) it will', '[{"id": "a", "text": "not provide any damping effect when rolling.", "correct": false}, {"id": "b", "text": "not suffer adverse yaw effects when turning.", "correct": false}, {"id": "c", "text": "tend to stall first at the root.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Correcting for a disturbance which has caused a rolling motion about the longitudinal axis would re- establish which of the following?', '[{"id": "a", "text": "Lateral stability.", "correct": true}, {"id": "b", "text": "Longitudinal stability.", "correct": false}, {"id": "c", "text": "Directional stability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Porpoising is an oscillatory motion in the', '[{"id": "a", "text": "yaw plane.", "correct": false}, {"id": "b", "text": "roll plane.", "correct": false}, {"id": "c", "text": "pitch plane.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Directional stability is maintained', '[{"id": "a", "text": "by the tailplane, and controlled by the elevators.", "correct": false}, {"id": "b", "text": "by the keel surface and fin, and controlled by the rudder.", "correct": true}, {"id": "c", "text": "by the mainplanes, and controlled by the ailerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Longitudinal stability is given by', '[{"id": "a", "text": "the fin.", "correct": false}, {"id": "b", "text": "the wing dihedral.", "correct": false}, {"id": "c", "text": "the horizontal tailplane.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lateral stability is given by', '[{"id": "a", "text": "the horizontal tailplane.", "correct": false}, {"id": "b", "text": "the ailerons.", "correct": false}, {"id": "c", "text": "the wing dihedral.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Stability about the lateral axis is given by', '[{"id": "a", "text": "the ailerons.", "correct": false}, {"id": "b", "text": "the horizontal tailplane.", "correct": true}, {"id": "c", "text": "wing dihedral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Sweepback of the wings will', '[{"id": "a", "text": "decrease lateral stability.", "correct": false}, {"id": "b", "text": "not affect the lateral stability.", "correct": false}, {"id": "c", "text": "increase lateral stability.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Dutch Roll is', '[{"id": "a", "text": "primarily a pitching instability.", "correct": false}, {"id": "b", "text": "a combined rolling and yawing motion.", "correct": true}, {"id": "c", "text": "a type of slow roll.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A high wing position gives', '[{"id": "a", "text": "more lateral stability than a low wing.", "correct": true}, {"id": "b", "text": "less lateral stability than a low wing.", "correct": false}, {"id": "c", "text": "the same lateral stability as a low wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Directional stability may be increased with', '[{"id": "a", "text": "pitch dampers.", "correct": false}, {"id": "b", "text": "horn balance.", "correct": false}, {"id": "c", "text": "yaw dampers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lateral stability may be increased with', '[{"id": "a", "text": "increased lateral dihedral.", "correct": true}, {"id": "b", "text": "increased lateral anhedral.", "correct": false}, {"id": "c", "text": "increased longitudinal dihedral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Longitudinal stability is increased if the', '[{"id": "a", "text": "CG is forward of the CP.", "correct": true}, {"id": "b", "text": "Thrust acts on a line below the total drag.", "correct": false}, {"id": "c", "text": "CP moves forward of the CG.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Directional stability is about the', '[{"id": "a", "text": "lateral axis.", "correct": false}, {"id": "b", "text": "longitudinal axis.", "correct": false}, {"id": "c", "text": "normal axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lateral stability is about the', '[{"id": "a", "text": "longitudinal axis.", "correct": true}, {"id": "b", "text": "normal axis.", "correct": false}, {"id": "c", "text": "vertical axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Longitudinal stability is provided by the', '[{"id": "a", "text": "horizontal stabilizer.", "correct": true}, {"id": "b", "text": "vertical stabilizer.", "correct": false}, {"id": "c", "text": "mainplane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the aircraft turns and side-slips', '[{"id": "a", "text": "the sweepback of the wing will correct the sideslip.", "correct": false}, {"id": "b", "text": "the keel surface will correct the sideslip.", "correct": false}, {"id": "c", "text": "the dihedral of the wing will correct the sideslip.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft disturbed from its normal flight path, and automatically returns to that normal flight path, without any action on the part of the pilot is known as', '[{"id": "a", "text": "aircraft stall.", "correct": false}, {"id": "b", "text": "aircraft instability.", "correct": false}, {"id": "c", "text": "aircraft stability.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The fin gives stability about which axis?', '[{"id": "a", "text": "Longitudinal axis.", "correct": false}, {"id": "b", "text": "Lateral axis.", "correct": false}, {"id": "c", "text": "Normal axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the nose of the aircraft is rotated about its lateral axis, what is its directional movement?', '[{"id": "a", "text": "Rolling or banking to the left or right.", "correct": false}, {"id": "b", "text": "Turning to the left or right.", "correct": false}, {"id": "c", "text": "Climbing or diving.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The function of an aircraft fin', '[{"id": "a", "text": "is to provide directional control.", "correct": false}, {"id": "b", "text": "is to provide straight airflow across the rudder.", "correct": false}, {"id": "c", "text": "is to provide stability about the normal axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Movement of an aircraft about its normal axis', '[{"id": "a", "text": "is rolling.", "correct": false}, {"id": "b", "text": "is yawing.", "correct": true}, {"id": "c", "text": "is pitching.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If, after a disturbance, an aeroplane initially returns to its equilibrium state', '[{"id": "a", "text": "it has neutral stability.", "correct": false}, {"id": "b", "text": "it has static stability and may be dynamically stable.", "correct": true}, {"id": "c", "text": "it is neutrally unstable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Stability of an aircraft is', '[{"id": "a", "text": "the tendency of the aircraft to return to its original trimmed position after having been displaced.", "correct": true}, {"id": "b", "text": "the tendency of the aircraft to stall at low airspeed.", "correct": false}, {"id": "c", "text": "the ability of the aircraft to rotate about an axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The three axes concerned with stability of an aircraft have normal axis through C of G. Lateral axis - wing tip to wing tip. Longitudinal axis - nose to tail but not', '[{"id": "a", "text": "through C of G.", "correct": false}, {"id": "b", "text": "longitudinal, lateral and normal axis all passing through aircraft centre of gravity.", "correct": true}, {"id": "c", "text": "longitudinal axis nose to tail, lateral axis at furthest span point, normal axis through centre of pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft returns to a position of equilibrium it is said to be', '[{"id": "a", "text": "positively stable.", "correct": true}, {"id": "b", "text": "neutrally stable.", "correct": false}, {"id": "c", "text": "negatively stable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The pendulum effect on a high wing aircraft', '[{"id": "a", "text": "has no effect on lateral stability.", "correct": false}, {"id": "b", "text": "increases lateral stability.", "correct": true}, {"id": "c", "text": "decreases lateral stability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'After a disturbance in pitch, an aircraft continues to oscillate at constant amplitude. It is', '[{"id": "a", "text": "longitudinally unstable.", "correct": false}, {"id": "b", "text": "longitudinally neutrally stable.", "correct": true}, {"id": "c", "text": "laterally unstable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On an aircraft with an all-moving tailplane nose up pitch is caused by', '[{"id": "a", "text": "decreasing tailplane incidence.", "correct": true}, {"id": "b", "text": "increasing tailplane incidence.", "correct": false}, {"id": "c", "text": "up movement of the trim tab.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What gives the aircraft directional stability?', '[{"id": "a", "text": "Vertical stabiliser.", "correct": true}, {"id": "b", "text": "Elevators.", "correct": false}, {"id": "c", "text": "Horizontal stabiliser.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In flight if the aircraft nose gets an upward gust of wind, what characteristic will have the greatest effect to counteract it?', '[{"id": "a", "text": "Wing Sweep.", "correct": false}, {"id": "b", "text": "Horizontal stabiliser and fuselage length.", "correct": true}, {"id": "c", "text": "Position of the centre of pressure relative to the centre of gravity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'To correct dutch roll you must damp oscillation around', '[{"id": "a", "text": "the longitudinal axis.", "correct": false}, {"id": "b", "text": "the lateral axis.", "correct": false}, {"id": "c", "text": "the vertical axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An elevator trim tab is used to', '[{"id": "a", "text": "counteract propeller torque.", "correct": false}, {"id": "b", "text": "prevent the control surface from stalling the airflow.", "correct": false}, {"id": "c", "text": "reduce control column forces on the pilot.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A high wing aircraft will be more', '[{"id": "a", "text": "laterally stable than a low wing aircraft.", "correct": true}, {"id": "b", "text": "longitudinally stable than a low wing aircraft.", "correct": false}, {"id": "c", "text": "directionally stable than a low wing aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'After an aircraft has been disturbed from its straight and level flight, it returns to its original attitude with a small amount of decreasing oscillation. The aircraft is', '[{"id": "a", "text": "statically stable but dynamically unstable.", "correct": false}, {"id": "b", "text": "statically unstable but dynamically stable.", "correct": false}, {"id": "c", "text": "statically stable and dynamically stable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If there is an increase of density, what effect would there be in aerodynamic dampening?', '[{"id": "a", "text": "Decreased.", "correct": false}, {"id": "b", "text": "Increased.", "correct": true}, {"id": "c", "text": "None.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Yawing is a rotation around', '[{"id": "a", "text": "the lateral axis obtained by the rudder.", "correct": false}, {"id": "b", "text": "the normal axis obtained by the rudder.", "correct": true}, {"id": "c", "text": "the normal axis obtained by the elevator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lateral stability is reduced by increasing', '[{"id": "a", "text": "dihedral.", "correct": false}, {"id": "b", "text": "sweepback.", "correct": false}, {"id": "c", "text": "anhedral.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Azimuth stability is dependent on', '[{"id": "a", "text": "dihedral.", "correct": false}, {"id": "b", "text": "keel and fin.", "correct": true}, {"id": "c", "text": "tailplane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Sweepback of the wings will', '[{"id": "a", "text": "increase lateral stability at high speeds only.", "correct": false}, {"id": "b", "text": "not affect lateral stability.", "correct": false}, {"id": "c", "text": "increase lateral stability at all speeds.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If you have an aircraft that is more laterally stable then directionally stable it will tend to', '[{"id": "a", "text": "bank.", "correct": false}, {"id": "b", "text": "slip.", "correct": true}, {"id": "c", "text": "skid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A centre of gravity position close to its aft limit will cause the aircraft to', '[{"id": "a", "text": "pitch nose down and increase its longitudinal stability.", "correct": false}, {"id": "b", "text": "pitch nose up and decrease its longitudinal stability.", "correct": true}, {"id": "c", "text": "pitch nose up and increase its longitudinal stability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A sharply swept wing will promote', '[{"id": "a", "text": "excessive lateral instability.", "correct": false}, {"id": "b", "text": "excessive longitudinal stability.", "correct": false}, {"id": "c", "text": "excessive lateral stability.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which control surfaces provide lateral control , also longitudinal control and stability?', '[{"id": "a", "text": "Ruddervators.", "correct": false}, {"id": "b", "text": "Tailerons.", "correct": true}, {"id": "c", "text": "Flapperons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If, after a disturbance, an aeroplane initially returns to its equilibrium state', '[{"id": "a", "text": "it has neutral stability.", "correct": false}, {"id": "b", "text": "it has static stability and may be dynamically stable.", "correct": true}, {"id": "c", "text": "it is neutrally unstable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Yaw dampers are designed to', '[{"id": "a", "text": "prevent dutch roll.", "correct": true}, {"id": "b", "text": "assist the pilot to move the rudder.", "correct": false}, {"id": "c", "text": "reduce the effect of crabbing due to cross winds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Tuck under occurs when', '[{"id": "a", "text": "a shock stall occurs on the outboard portion of swept wing.", "correct": true}, {"id": "b", "text": "a shock stall warning occurs on the inboard position of a straight wing.", "correct": false}, {"id": "c", "text": "the aircraft reaches Mcrit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The lateral axis is', '[{"id": "a", "text": "a straight line through the CG at right angles to the longitudinal and lateral axis.", "correct": false}, {"id": "b", "text": "a straight line through the CG from nose to tail.", "correct": false}, {"id": "c", "text": "a straight line through the CG parallel to a line joining the wingtips.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The main factors which affect longitudinal stability are', '[{"id": "a", "text": "design of the fuselage and position of the CG.", "correct": false}, {"id": "b", "text": "design of the mainplane and position of the CG.", "correct": false}, {"id": "c", "text": "design of the tailplane and position of the CG.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A yawing motion provides what kind of Stability?', '[{"id": "a", "text": "Directional.", "correct": true}, {"id": "b", "text": "Lateral.", "correct": false}, {"id": "c", "text": "Longitudinal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Where would you find the normal axis?', '[{"id": "a", "text": "Through C of G at right angles to longitudinal and lateral axis.", "correct": true}, {"id": "b", "text": "Vertically through CofP.", "correct": false}, {"id": "c", "text": "In line with the wing tips through C of G.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When a aircraft is in a slideslip and is yawing the', '[{"id": "a", "text": "the fin will correct the yawing motion.", "correct": true}, {"id": "b", "text": "the effective keel area will make the ac yaw further into the direction of the sideslip.", "correct": false}, {"id": "c", "text": "the dihedral will prevent the yaw motion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As a consequence of the C of G being close to its aft limit', '[{"id": "a", "text": "the stick forces to manoeuvre longitudinally will be low due to low stability.", "correct": true}, {"id": "b", "text": "the stick forces will be high in fore and aft pitch, due to the high longitudinal stability.", "correct": false}, {"id": "c", "text": "the stick forces when pitching the nose down will be very high.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With the C of G on its forward limit', '[{"id": "a", "text": "the change in control loading is dependant on the position of the CofP.", "correct": false}, {"id": "b", "text": "control loading decreases.", "correct": false}, {"id": "c", "text": "control loading increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An undercarriage leg in flight produces 3 lbs of drag at 100kts. If speed is increased to 200kts the drag would be', '[{"id": "a", "text": "12 lbs.", "correct": true}, {"id": "b", "text": "9 lbs.", "correct": false}, {"id": "c", "text": "6 lbs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A stall warning device must be set to operate', '[{"id": "a", "text": "at a speed just above stalling speed.", "correct": true}, {"id": "b", "text": "at a speed just below stalling speed.", "correct": false}, {"id": "c", "text": "at the stalling speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In cruise the weight of an aeroplane is decreasing as fuel is used. A stall would occur', '[{"id": "a", "text": "at a lower speed.", "correct": true}, {"id": "b", "text": "at the same speed.", "correct": false}, {"id": "c", "text": "at a higher speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As height increases, with angle of attack and speed constant', '[{"id": "a", "text": "lift will remain constant.", "correct": false}, {"id": "b", "text": "lift Increases.", "correct": false}, {"id": "c", "text": "lift decreases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a swept wing aircraft if both wing tip sections lose lift simultaneously the aircraft will', '[{"id": "a", "text": "roll.", "correct": false}, {"id": "b", "text": "pitch nose up.", "correct": true}, {"id": "c", "text": "pitch nose down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lift on a delta wing aircraft', '[{"id": "a", "text": "increases with an increased angle of incidence (angle of attack).", "correct": true}, {"id": "b", "text": "decreases with an increase in angle of incidence (angle of attack).", "correct": false}, {"id": "c", "text": "does not change with a change in angle of incidence (angle of attack).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a straight wing aircraft, stall commences at the', '[{"id": "a", "text": "root on a high thickness ratio wing.", "correct": true}, {"id": "b", "text": "tip on a high thickness ratio wing.", "correct": false}, {"id": "c", "text": "tip on a low thickness ratio wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a high wing aircraft in a turn', '[{"id": "a", "text": "the up-going wing loses lift causing a de-stabilizing effect.", "correct": false}, {"id": "b", "text": "the down-going wing gains lift causing a stabilizing effect.", "correct": true}, {"id": "c", "text": "the down-going wing loses lift causing a de-stabilizing effect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'For the same angle of attack, the lift on a delta wing', '[{"id": "a", "text": "is greater than the lift on a high aspect ratio wing.", "correct": false}, {"id": "b", "text": "is lower than the lift on a high aspect ratio wing.", "correct": true}, {"id": "c", "text": "is the same as the lift on a high aspect ratio wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The ISA?', '[{"id": "a", "text": "is taken from the equator.", "correct": false}, {"id": "b", "text": "is taken from 45 degrees latitude.", "correct": true}, {"id": "c", "text": "assumes a standard day.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The thrust-drag couple overcomes the lift-weight couple. What direction of force is required to be produced by the tail of the aircraft to maintain straight and level flight', '[{"id": "a", "text": "upwards.", "correct": true}, {"id": "b", "text": "downwards.", "correct": false}, {"id": "c", "text": "sideways.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'During a turn, the stalling angle', '[{"id": "a", "text": "increases.", "correct": false}, {"id": "b", "text": "decreases.", "correct": false}, {"id": "c", "text": "remains the same.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The C of G moves in flight. The most likely cause of this is', '[{"id": "a", "text": "movement of passengers.", "correct": false}, {"id": "b", "text": "movement of the centre of pressure.", "correct": false}, {"id": "c", "text": "consumption of fuel and oils.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The C of P is the point where', '[{"id": "a", "text": "all the forces on an aircraft act.", "correct": false}, {"id": "b", "text": "the three axis of rotation meet.", "correct": false}, {"id": "c", "text": "the lift can be said to act.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The three axis of an aircraft act through the', '[{"id": "a", "text": "C of G.", "correct": true}, {"id": "b", "text": "C of P.", "correct": false}, {"id": "c", "text": "stagnation point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When the weight of an aircraft increases, the minimum drag speed', '[{"id": "a", "text": "decreases.", "correct": false}, {"id": "b", "text": "increases.", "correct": true}, {"id": "c", "text": "remains the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft will have', '[{"id": "a", "text": "less gliding distance if it has more payload.", "correct": false}, {"id": "b", "text": "more gliding distance if it has more payload.", "correct": false}, {"id": "c", "text": "the same gliding distance if it has more payload.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What happens to load factor as you decrease turn radius?', '[{"id": "a", "text": "It increases.", "correct": true}, {"id": "b", "text": "It decreases.", "correct": false}, {"id": "c", "text": "It remains constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If you steepen the angle of a banked turn without increasing airspeed or angle of attack, what will the aircraft do?', '[{"id": "a", "text": "It will remain at the same height.", "correct": false}, {"id": "b", "text": "It will sideslip with attendant loss of height.", "correct": true}, {"id": "c", "text": "It will stall.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft wing tends to stall first at', '[{"id": "a", "text": "the tip due to a higher ratio thickness/chord.", "correct": false}, {"id": "b", "text": "the tip due to a lower ratio thickness/chord.", "correct": false}, {"id": "c", "text": "the root due to a higher ratio thickness/chord.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'To stop aircraft decreasing in height during a sideslip, the pilot can', '[{"id": "a", "text": "advance the throttle.", "correct": true}, {"id": "b", "text": "pull back on the control column.", "correct": false}, {"id": "c", "text": "adjust the rudder position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What control surface movements will make an aircraft fitted with ruddervators yaw to the left?', '[{"id": "a", "text": "Left ruddervator lowered, right ruddervator raised.", "correct": false}, {"id": "b", "text": "Right ruddervator lowered, left ruddervator raised.", "correct": true}, {"id": "c", "text": "Both ruddervators raised.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When a leading edge slat opens, there is a gap between the slat and the wing. This is', '[{"id": "a", "text": "to allow it to retract back into the wing.", "correct": false}, {"id": "b", "text": "to allow air through to re-energize the boundary layer on top of the wing.", "correct": true}, {"id": "c", "text": "to keep the area of the wing the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the wing tips stall before the root on a swept wing aircraft, the aircraft will', '[{"id": "a", "text": "roll.", "correct": false}, {"id": "b", "text": "pitch nose up.", "correct": true}, {"id": "c", "text": "pitch nose down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The thrust-drag couple overcomes the lift-weight couple. What direction of force is required to be produced by the tail of the aircraft to maintain straight and level flight?', '[{"id": "a", "text": "Upwards.", "correct": true}, {"id": "b", "text": "Downwards.", "correct": false}, {"id": "c", "text": "Sideways.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The vertical fin of a single engined aircraft is', '[{"id": "a", "text": "parallel with both the longitudinal axis and vertical axis.", "correct": false}, {"id": "b", "text": "parallel with the longitudinal axis but not the vertical axis.", "correct": false}, {"id": "c", "text": "parallel with the vertical axis but not the longitudinal axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Aircraft flying in the transonic range most often utilize', '[{"id": "a", "text": "sweptback wings.", "correct": true}, {"id": "b", "text": "advanced supercritical airfoils.", "correct": false}, {"id": "c", "text": "high wings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which type of flap changes the area of the wing?', '[{"id": "a", "text": "Fowler.", "correct": true}, {"id": "b", "text": "Split.", "correct": false}, {"id": "c", "text": "Slotted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft, which is longitudinally stable, will tend to return to level flight after a movement about which axis?', '[{"id": "a", "text": "Pitch.", "correct": true}, {"id": "b", "text": "Roll.", "correct": false}, {"id": "c", "text": "Yaw.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Vortex generators on the wing are most effective at', '[{"id": "a", "text": "high speed.", "correct": true}, {"id": "b", "text": "low speed.", "correct": false}, {"id": "c", "text": "high angles of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Lateral control of an aircraft at high angle of attack can be maximized by using', '[{"id": "a", "text": "fences.", "correct": false}, {"id": "b", "text": "vortex generators.", "correct": false}, {"id": "c", "text": "wing slots.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Stall strips are always', '[{"id": "a", "text": "made of metal.", "correct": false}, {"id": "b", "text": "on the leading edge of a wing.", "correct": true}, {"id": "c", "text": "fitted forward of the ailerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Due to the interference of the airflow on a high wing aircraft between the fuselage and the wings, the lateral stability of the aircraft in a gusty wind situation will cause', '[{"id": "a", "text": "the upper wing to increase its lift.", "correct": false}, {"id": "b", "text": "the upper wing to decrease its lift.", "correct": true}, {"id": "c", "text": "the lower wing to decrease its lift.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft banks into a turn. No change is made to the airspeed or angle of attack. What will happen?', '[{"id": "a", "text": "The aircraft enters a side slip and begins to lose altitude.", "correct": true}, {"id": "b", "text": "The aircraft turns with no loss of height.", "correct": false}, {"id": "c", "text": "The aircraft yaws and slows down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a high winged aircraft, what effect will the fuselage have on the up-going wing?', '[{"id": "a", "text": "The up-going wing will have a decrease in angle of attack and therefore a decrease in lift.", "correct": true}, {"id": "b", "text": "The down-going will have a decrease in angle of attack and therefore a decrease in lift.", "correct": false}, {"id": "c", "text": "The up-going wing will have an increase in angle of attack and therefore a decrease in lift.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The angle of attack which gives the best L/D ratio', '[{"id": "a", "text": "decreases with a decrease in density.", "correct": false}, {"id": "b", "text": "in unaffected by density changes.", "correct": true}, {"id": "c", "text": "increases with a decrease in density.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'True stalling speed of an aircraft increases with altitude', '[{"id": "a", "text": "because reduced temperature causes compressibility effect.", "correct": false}, {"id": "b", "text": "because air density is reduced.", "correct": true}, {"id": "c", "text": "because humidity is increased and this increases drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The "wing setting angle" is commonly known as', '[{"id": "a", "text": "angle of incidence.", "correct": true}, {"id": "b", "text": "angle of attack.", "correct": false}, {"id": "c", "text": "angle of dihedral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a very humid day, an aircraft taking off would require', '[{"id": "a", "text": "a shorter take off run.", "correct": false}, {"id": "b", "text": "a longer take off run.", "correct": true}, {"id": "c", "text": "humidity does not affect the take off run.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft is flying at 350 MPH, into a head wind of 75 MPH, what will its ground speed be?', '[{"id": "a", "text": "175 mph.", "correct": false}, {"id": "b", "text": "275 mph.", "correct": true}, {"id": "c", "text": "200 mph.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the four forces act on an aircraft?', '[{"id": "a", "text": "Lift, gravity, thrust and drag.", "correct": true}, {"id": "b", "text": "Weight, gravity, thrust and drag.", "correct": false}, {"id": "c", "text": "Lift, weight, gravity and drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Correcting for a disturbance which has caused a rolling motion about the longitudinal axis would re- establish which of the following?', '[{"id": "a", "text": "Lateral stability.", "correct": true}, {"id": "b", "text": "Directional stability.", "correct": false}, {"id": "c", "text": "Longitudinal stability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'To achieve the maximum distance in a glide, the recommended air speed is', '[{"id": "a", "text": "as close to the stall as practical.", "correct": false}, {"id": "b", "text": "as high as possible with VNE.", "correct": false}, {"id": "c", "text": "the speed where the L/D ratio is maximum.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Proposing is an oscillatory motion in the', '[{"id": "a", "text": "pitch plane.", "correct": true}, {"id": "b", "text": "roll plane.", "correct": false}, {"id": "c", "text": "yaw plane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Due to the interference effects of the fuselage, when a high wing aeroplane sideslips', '[{"id": "a", "text": "the accompanying rolling due to keel surface area is destabilizing.", "correct": false}, {"id": "b", "text": "the accompanying lift changes on the wings produces a stabilizing effect.", "correct": true}, {"id": "c", "text": "the accompanying rolling due to the fin is destabilizing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The power required in a horizontal turn', '[{"id": "a", "text": "is greater than that for level flight at the same airspeed.", "correct": true}, {"id": "b", "text": "must be the same as that for level flight at the same airspeed.", "correct": false}, {"id": "c", "text": "is less than that for level flight at the same airspeed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A wing mounted stall sensing device is located', '[{"id": "a", "text": "usually on the under surface.", "correct": true}, {"id": "b", "text": "always at the wing tip.", "correct": false}, {"id": "c", "text": "always on the top surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'For an aircraft in a glide', '[{"id": "a", "text": "thrust, drag, lift and weight act on the aircraft.", "correct": false}, {"id": "b", "text": "weight, lift and drag act on the aircraft.", "correct": true}, {"id": "c", "text": "weight and drag only act on the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aspect ratio of 8 would mean', '[{"id": "a", "text": "span 64, mean chord 8.", "correct": true}, {"id": "b", "text": "mean chord 64 , span 8.", "correct": false}, {"id": "c", "text": "span squared 64 ,chord 8.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft in level flight loses engine power it will', '[{"id": "a", "text": "pitch nose up.", "correct": false}, {"id": "b", "text": "pitch nose down.", "correct": true}, {"id": "c", "text": "not change pitch without drag increasing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The lift /drag ratio at stall', '[{"id": "a", "text": "increases.", "correct": false}, {"id": "b", "text": "decreases.", "correct": true}, {"id": "c", "text": "is unchanged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a straight unswept wing, stall occurs at', '[{"id": "a", "text": "the thick portion at the wing root.", "correct": true}, {"id": "b", "text": "the thick portion at the wing tip.", "correct": false}, {"id": "c", "text": "the thin portion at the wing tip.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'During a climb from a dive', '[{"id": "a", "text": "the thrust required is greater than required for level flight.", "correct": true}, {"id": "b", "text": "the thrust required is lower than for level flight.", "correct": false}, {"id": "c", "text": "the thrust required is the same as for level flight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When power is off, the aircraft will pitch', '[{"id": "a", "text": "nose down.", "correct": true}, {"id": "b", "text": "nose up.", "correct": false}, {"id": "c", "text": "trim level.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Angle of attack on a down going wing in a roll', '[{"id": "a", "text": "increases.", "correct": true}, {"id": "b", "text": "decreases.", "correct": false}, {"id": "c", "text": "unaffected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the angle of attack of a wing is increased in level flight', '[{"id": "a", "text": "the Cof G moves aft and the Cof P forward.", "correct": false}, {"id": "b", "text": "the Cof P and transition point move forward.", "correct": true}, {"id": "c", "text": "the Cof P moves forward and the stagnation point aft over the upper surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the angle of attack is increased the Centre of Pressure will', '[{"id": "a", "text": "move forward.", "correct": true}, {"id": "b", "text": "move rearward.", "correct": false}, {"id": "c", "text": "remain stationary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A high aspect ratio wing has a', '[{"id": "a", "text": "increased induced drag.", "correct": false}, {"id": "b", "text": "decreased induced drag.", "correct": true}, {"id": "c", "text": "decreased skin friction drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On an aircraft in an unpowered steady speed descent', '[{"id": "a", "text": "the lift equals the weight.", "correct": false}, {"id": "b", "text": "the weight equals the drag.", "correct": false}, {"id": "c", "text": "the weight equals the resultant of the lift and drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When an aircraft rolls to enter a turn and power is not increased', '[{"id": "a", "text": "the lift equals the weight.", "correct": false}, {"id": "b", "text": "the lift is greater than the weight.", "correct": false}, {"id": "c", "text": "the lift is less than the weight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When an aircraft with a C of G forward of the C of P rolls, the nose of the aircraft will', '[{"id": "a", "text": "stay level.", "correct": false}, {"id": "b", "text": "rise.", "correct": false}, {"id": "c", "text": "drop.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In a bank, the weight is', '[{"id": "a", "text": "increased.", "correct": false}, {"id": "b", "text": "decreased.", "correct": false}, {"id": "c", "text": "the same.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'L/D ratio is', '[{"id": "a", "text": "higher at supersonic cruise speed.", "correct": false}, {"id": "b", "text": "higher at sub sonic speed.", "correct": true}, {"id": "c", "text": "the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The power required at low altitude for a given IAS is', '[{"id": "a", "text": "the same as at high altitude.", "correct": false}, {"id": "b", "text": "higher.", "correct": false}, {"id": "c", "text": "lower.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the stall speed is 75 knots what is the same stall speed in mph', '[{"id": "a", "text": "75 x 0.87.", "correct": false}, {"id": "b", "text": "75 / 0.87.", "correct": true}, {"id": "c", "text": "75 / 0.87 x relative density.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An untapered wing will', '[{"id": "a", "text": "have no yaw effect in banking.", "correct": false}, {"id": "b", "text": "have no change in induced drag in the bank.", "correct": false}, {"id": "c", "text": "stall at the root first.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The lift drag ratio is', '[{"id": "a", "text": "higher at mach numbers above supersonic.", "correct": false}, {"id": "b", "text": "higher at sub sonic mach numbers.", "correct": true}, {"id": "c", "text": "the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The force opposing thrust is', '[{"id": "a", "text": "drag.", "correct": true}, {"id": "b", "text": "lift.", "correct": false}, {"id": "c", "text": "Weight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Movement of an aircraft about its lateral axis', '[{"id": "a", "text": "is pitching.", "correct": true}, {"id": "b", "text": "is rolling.", "correct": false}, {"id": "c", "text": "is yawing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At what altitude is tropopause', '[{"id": "a", "text": "63,000 ft.", "correct": false}, {"id": "b", "text": "36,000 ft.", "correct": true}, {"id": "c", "text": "57,000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following act in opposition to forward movement?', '[{"id": "a", "text": "Lift.", "correct": false}, {"id": "b", "text": "Gravity.", "correct": false}, {"id": "c", "text": "Drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Directional control is provided by', '[{"id": "a", "text": "horizontal stabilizer.", "correct": false}, {"id": "b", "text": "rudder.", "correct": true}, {"id": "c", "text": "elevator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'About which axis of the aircraft does a rolling motion take place?', '[{"id": "a", "text": "Normal axis.", "correct": false}, {"id": "b", "text": "Longitudinal axis.", "correct": true}, {"id": "c", "text": "Lateral axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which motion happens about the lateral axis?', '[{"id": "a", "text": "Pitching.", "correct": true}, {"id": "b", "text": "Yawing.", "correct": false}, {"id": "c", "text": "Rolling.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which of the following describes the "Empennage" ?', '[{"id": "a", "text": "Nose section of an aircraft, including the cockpit.", "correct": false}, {"id": "b", "text": "Tail section of the aircraft, including fin, rudder, tail plane and elevators.", "correct": true}, {"id": "c", "text": "The wings, including the ailerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When an aircraft is in straight and level unaccelerated flight, which of the following is correct?', '[{"id": "a", "text": "Lift and weight are equal, and thrust and drag are equal.", "correct": true}, {"id": "b", "text": "Lift greater than weight, and thrust greater than drag.", "correct": false}, {"id": "c", "text": "Lift greater than weight, and thrust is less than drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'What is the horizontal movement of the nose of the aircraft called?', '[{"id": "a", "text": "Rolling movement.", "correct": false}, {"id": "b", "text": "Pitching movement.", "correct": false}, {"id": "c", "text": "Yawing movement.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When air flow velocity over an upper cambered surface of an aerofoil decreases, what takes place?', '[{"id": "a", "text": "Pressure increases, lift decreases.", "correct": true}, {"id": "b", "text": "Pressure increases, lift increases.", "correct": false}, {"id": "c", "text": "Pressure decreases, lift increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When an aircraft is banked, the horizontal component of the lift', '[{"id": "a", "text": "will tend to make the aircraft follow a circular path.", "correct": true}, {"id": "b", "text": "will oppose the tendency of the aircraft to follow a circular path.", "correct": false}, {"id": "c", "text": "will oppose the weight thus requiring more total lift in the turn.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With reference to altimeters QFE is', '[{"id": "a", "text": "setting aerodrome atmospheric pressure so that an altimeter reads zero on landing and take off.", "correct": true}, {"id": "b", "text": "quite fine equipment.", "correct": false}, {"id": "c", "text": "the manufacturers registered name.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Under the ICAO "Q" code there are which three settings?', '[{"id": "a", "text": "QFE, QNH, QNE.", "correct": true}, {"id": "b", "text": "QEF, QNH, QEN.", "correct": false}, {"id": "c", "text": "QE, QN, QQE.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With an increase in aspect ratio for a given ISA, induced drag will', '[{"id": "a", "text": "remain constant.", "correct": false}, {"id": "b", "text": "increase.", "correct": false}, {"id": "c", "text": "reduce.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With increasing altitude the angle at which a wing will stall', '[{"id": "a", "text": "remains the same.", "correct": true}, {"id": "b", "text": "reduces.", "correct": false}, {"id": "c", "text": "increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the speed of an aircraft increases the profile drag', '[{"id": "a", "text": "increases.", "correct": true}, {"id": "b", "text": "decreases.", "correct": false}, {"id": "c", "text": "decreases at first then increase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The thrust-drag couple overcomes the lift-weight couple. What force must the tail of the aircraft exert to maintain the aircraft in a level attitude?', '[{"id": "a", "text": "Down.", "correct": false}, {"id": "b", "text": "Up.", "correct": true}, {"id": "c", "text": "Sideways.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If gauge pressure on a standard day is 25 PSI, the absolute pressure is', '[{"id": "a", "text": "10.3 PSI.", "correct": false}, {"id": "b", "text": "43.8 PSI.", "correct": false}, {"id": "c", "text": "39.7 PSI.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which atmospheric conditions will cause the true landing speed of an aircraft to be the greatest?', '[{"id": "a", "text": "Low temperature with low humidity.", "correct": false}, {"id": "b", "text": "High temperature with low humidity.", "correct": false}, {"id": "c", "text": "High temperature with high humidity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If all, or a significant part of a stall strip is missing on an aeroplane wing, a likely result will be', '[{"id": "a", "text": "increased lift in the area of installation on the opposite wing at high angles of attack.", "correct": false}, {"id": "b", "text": "asymmetrical aileron control at low angles of attack.", "correct": false}, {"id": "c", "text": "asymmetrical aileron control at or near stall angles of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Which type of flap increases the area of the wing?', '[{"id": "a", "text": "Plain Flap.", "correct": false}, {"id": "b", "text": "Fowler Flap.", "correct": true}, {"id": "c", "text": "All flaps.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Deployment of flaps will result in', '[{"id": "a", "text": "a decrease in stall angle.", "correct": true}, {"id": "b", "text": "an increase in stall angle.", "correct": false}, {"id": "c", "text": "a decrease in angle of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The angle of attack of an aerofoil section is the angle between the', '[{"id": "a", "text": "chord line and the relative airflow.", "correct": true}, {"id": "b", "text": "underside of the wing surface and the mean airflow.", "correct": false}, {"id": "c", "text": "chord line and the centre line of the fuselage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Krueger Flaps are normally fitted to', '[{"id": "a", "text": "the trailing edge of the wings.", "correct": false}, {"id": "b", "text": "the tips of the wings.", "correct": false}, {"id": "c", "text": "the leading edge of the wings.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A wing with a very high aspect ratio (in comparison with a low aspect ratio wing) will have', '[{"id": "a", "text": "increased drag at high angles of attack.", "correct": false}, {"id": "b", "text": "a high stall speed.", "correct": false}, {"id": "c", "text": "poor control qualities at low airspeeds.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'After an aircraft has been disturbed from its straight and level flight, it returns to its original attitude with a small amount of decreasing oscillation. The aircraft is', '[{"id": "a", "text": "statically stable but dynamically unstable.", "correct": false}, {"id": "b", "text": "statically unstable but dynamically stable.", "correct": false}, {"id": "c", "text": "statically stable and dynamically stable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An increase in the speed at which an aerofoil passes through the air increases lift because the increased speed of the airflow creates a greater pressure differential between the upper and lower', '[{"id": "a", "text": "surfaces.", "correct": true}, {"id": "b", "text": "the increased speed of the airflow creates a lesser pressure differential between the upper and lower surfaces.", "correct": false}, {"id": "c", "text": "the increased velocity of the relative wind increases the angle of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The Lift/Drag ratio of a wing at the stalling angle is', '[{"id": "a", "text": "of a negative value.", "correct": false}, {"id": "b", "text": "low.", "correct": true}, {"id": "c", "text": "high.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'For a given angle of attack induced drag is', '[{"id": "a", "text": "greater on a high aspect ratio wing.", "correct": false}, {"id": "b", "text": "greater towards the wing root.", "correct": false}, {"id": "c", "text": "greater on a low aspect ratio wing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft flying in "ground effect" will produce', '[{"id": "a", "text": "more lift than a similar aircraft outside of ground effect.", "correct": true}, {"id": "b", "text": "less lift than a similar aircraft outside of ground effect.", "correct": false}, {"id": "c", "text": "the same lift as a similar aircraft outside of ground effect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When maintaining level flight an increase in speed will', '[{"id": "a", "text": "cause the C of P to move aft.", "correct": true}, {"id": "b", "text": "cause the C of P to move forward.", "correct": false}, {"id": "c", "text": "have no affect on the position of the C of P.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Bernoulli`s equation shows that', '[{"id": "a", "text": "at constant velocity the kinetic energy of the air changes with a change of height.", "correct": false}, {"id": "b", "text": "with a change in speed at constant height both kinetic and potential energies change.", "correct": false}, {"id": "c", "text": "with a change in velocity at constant height the static pressure will change.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The maximum lift/drag ratio of a wing occurs', '[{"id": "a", "text": "at the angle of attack where the wing develops its maximum lift.", "correct": false}, {"id": "b", "text": "during take off.", "correct": false}, {"id": "c", "text": "at an angle below which the wing develops max lift.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A wing develops 10,000N of lift at 100knots. Assuming the wing remains at the same angle of attack and remains at the same altitude, how much lift will it develop at 300knots?', '[{"id": "a", "text": "900,000 N.", "correct": false}, {"id": "b", "text": "90,000N.", "correct": true}, {"id": "c", "text": "30,000N.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A stalled aerofoil has a lift/drag ratio', '[{"id": "a", "text": "more than the lift/drag ratio prior to stall.", "correct": false}, {"id": "b", "text": "zero.", "correct": false}, {"id": "c", "text": "less than the lift/drag ratio prior to stall.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'At low forward speed', '[{"id": "a", "text": "increased downwash reduces tailplane effectiveness.", "correct": true}, {"id": "b", "text": "increased downwash increases tailplane effectiveness.", "correct": false}, {"id": "c", "text": "excessive rudder movement may cause fin to stall.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On some modern aircraft a stall warning will automatically', '[{"id": "a", "text": "increase thrust.", "correct": false}, {"id": "b", "text": "extend outboard slats.", "correct": false}, {"id": "c", "text": "cause a pitch nose down movement.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The spanwise component of the airflow is', '[{"id": "a", "text": "greater at higher speeds.", "correct": false}, {"id": "b", "text": "less at higher speeds.", "correct": true}, {"id": "c", "text": "unaffected by speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The highest lift/drag ratio is greatest at', '[{"id": "a", "text": "low altitudes.", "correct": false}, {"id": "b", "text": "the point just before the stalling angle.", "correct": false}, {"id": "c", "text": "the optimum angle of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'IAS for a stall will', '[{"id": "a", "text": "increase with altitude.", "correct": false}, {"id": "b", "text": "decrease with altitude.", "correct": false}, {"id": "c", "text": "roughly remain the same for all altitude.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the radius of a turn is reduced the load factor will', '[{"id": "a", "text": "increase.", "correct": true}, {"id": "b", "text": "decrease.", "correct": false}, {"id": "c", "text": "remain the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'A constant rate of climb is determined by', '[{"id": "a", "text": "weight.", "correct": false}, {"id": "b", "text": "wind speed.", "correct": false}, {"id": "c", "text": "excess engine power.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With an aircraft in bank, the upper wing produces more drag. To compensate', '[{"id": "a", "text": "the rudder is operated.", "correct": true}, {"id": "b", "text": "when bank angle is achieved then the ailerons are operated in the opposite direction to cause the opposite", "correct": false}, {"id": "c", "text": "angle of attack is increased.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'On a high winged aircraft in a banked turn, which of the following are true?', '[{"id": "a", "text": "The down-going wing loses lift causing a stabilizing effect.", "correct": false}, {"id": "b", "text": "The up-going wing loses lift causing a stabilizing effect.", "correct": true}, {"id": "c", "text": "The wing dihedral causes a stabilizing effect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If an aircraft true airspeed is halved, its indicated airspeed is reduced by', '[{"id": "a", "text": "half.", "correct": true}, {"id": "b", "text": "factor of four.", "correct": false}, {"id": "c", "text": "It is not reduced, it is doubled.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When a slat is retracted it moves', '[{"id": "a", "text": "towards the upper leading edge of the wing.", "correct": true}, {"id": "b", "text": "towards the lower leading edge of the wing.", "correct": false}, {"id": "c", "text": "towards the center of the leading edge of the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In a turn the up-going wing causes a', '[{"id": "a", "text": "de-stabilizing effect due to increased AoA.", "correct": false}, {"id": "b", "text": "de-stabilizing effect due to decreased AoA.", "correct": false}, {"id": "c", "text": "stabilizing effect due to decreased AoA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'The stagnation point consists of', '[{"id": "a", "text": "dynamic and static air pressure.", "correct": true}, {"id": "b", "text": "static air pressure.", "correct": false}, {"id": "c", "text": "dynamic air pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'As the angle of attack increases the centre of pressure will', '[{"id": "a", "text": "move rearward.", "correct": false}, {"id": "b", "text": "remain static.", "correct": false}, {"id": "c", "text": "move forward.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft entering a level turn will require more lift', '[{"id": "a", "text": "only if there is an increase in speed.", "correct": false}, {"id": "b", "text": "only if there is an increase in angle of attack.", "correct": false}, {"id": "c", "text": "in all cases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'Pulling the control column and rotating to the left causes', '[{"id": "a", "text": "elevator down, left aileron down.", "correct": false}, {"id": "b", "text": "elevator up, left aileron up.", "correct": true}, {"id": "c", "text": "elevator down, left aileron up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'If the aircraft is slipping in turn', '[{"id": "a", "text": "the bank angle is too great.", "correct": true}, {"id": "b", "text": "the bank angle is too small.", "correct": false}, {"id": "c", "text": "the nose of the aircraft is too low.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'In normal flight conditions, an increase in aircraft speed', '[{"id": "a", "text": "causes the nose of the aircraft to drop.", "correct": false}, {"id": "b", "text": "causes the nose of the aircraft to lift.", "correct": true}, {"id": "c", "text": "the nose remains in the same position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'An aircraft sideslips. What helps to restore the aircraft?', '[{"id": "a", "text": "Fin gives rolling movement.", "correct": false}, {"id": "b", "text": "Dihedral causes the aircraft to roll straight and the fin increases the yaw rate.", "correct": true}, {"id": "c", "text": "Tailplane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'For an aircraft climbing at a constant IAS the Mach number will', '[{"id": "a", "text": "increase.", "correct": true}, {"id": "b", "text": "decrease.", "correct": false}, {"id": "c", "text": "remain constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'With the flaps lowered, the stalling speed will', '[{"id": "a", "text": "increase.", "correct": false}, {"id": "b", "text": "decrease.", "correct": true}, {"id": "c", "text": "remain the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When flying close to the stall speed a pilot applies left rudder the aircraft will', '[{"id": "a", "text": "pitch nose up.", "correct": false}, {"id": "b", "text": "roll to the left.", "correct": false}, {"id": "c", "text": "stall the left wing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When an aircraft is in a bank, the upper wing produces more drag. To compensate', '[{"id": "a", "text": "the rudder is operated.", "correct": true}, {"id": "b", "text": "when bank angle is achieved then the ailerons are operated in the opposite direction to cause the opposite", "correct": false}, {"id": "c", "text": "angle of attack is increased (pitch up).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M08.18'), 'When flaps are down it will', '[{"id": "a", "text": "increase AoA and increase slow speed stability.", "correct": true}, {"id": "b", "text": "decrease AoA and decrease slow speed stability.", "correct": false}, {"id": "c", "text": "the AoA remains the same on both wings.", "correct": false}]'::jsonb, '{B1,B2}');
